const CATALOG=[{"id": "초1~2-듣기-01", "g": "초1~2", "a": "듣기", "lv": 1, "n": 1, "t": "물건 이름을 듣고 찾아요", "goal": "짧고 쉬운 단어를 듣고 대상을 찾을 수 있어요.", "std": "짧고 쉬운 단어를 듣고 대상을 찾을 수 있다.", "codes": "L-1-1-1, L-1-1-2, L-1-1-3", "theme": "교실 물건", "acts": ["물건 이름 알아보기 — 그림을 눌러 이름을 들어요.", "듣고 찾기 — 선생님이 말한 물건을 골라요.", "두 가지 듣고 찾기 — 두 물건을 한 번에 듣고 골라요.", "들은 순서대로 놓기 — 들은 차례대로 끌어다 놓아요."], "file": "lessons/g12-L-01.html", "st": "open"}, {"id": "초1~2-듣기-02", "g": "초1~2", "a": "듣기", "lv": 1, "n": 2, "t": "만나고 헤어질 때 인사해요", "goal": "간단한 인사말을 듣고 이해할 수 있어요.", "std": "간단한 인사말을 듣고 이해할 수 있다.", "codes": "L-1-2-1, L-1-2-2", "theme": "인사", "acts": ["낱말·표현 익히기: 안녕하세요, 안녕히 계세요, 안녕히 가세요, 내일 봐요", "만나고 헤어질 때 인사말(안녕하세요, 안녕히 계세요 등)에 답한다.", "만나고 헤어질 때 인사말(안녕히 가세요, 내일 봐요. 등)에 알맞은 표정이나 몸짓으로 반응한다.", "확인(진단형 L-1-2-1·L-1-2-2 섞기)"], "file": "lessons/g12-L-02.html", "st": "soon"}, {"id": "초1~2-듣기-03", "g": "초1~2", "a": "듣기", "lv": 1, "n": 3, "t": "선생님 말을 듣고 움직여요", "goal": "교사의 간단한 지시를 듣고 따를 수 있어요.", "std": "교사의 간단한 지시를 듣고 따를 수 있다.", "codes": "L-1-3-1, L-1-3-2, L-1-3-3", "theme": "교실 지시", "acts": ["낱말·표현 익히기: 일어나세요, 앉으세요, 오른쪽으로 가세요, 교실로 들어가세요, 책을 펴세요, 이름을 쓰세요", "교사의 행동 지시(일어나세요, 앉으세요.등)를 듣고, 해당 행동을 수행한다.", "교사의 방향을 포함한 지시(오른쪽으로 가세요. 교실로 들어가세요. 등)를 듣고, 해당 행동을 수행한다.", "확인(진단형) 목적어/부사어를 포함한 지시(책을 펴세요, 이름을 쓰세요. 자리에 앉으세요. 등)를 듣고, 해당 행동을 수…"], "file": "lessons/g12-L-03.html", "st": "soon"}, {"id": "초1~2-듣기-04", "g": "초1~2", "a": "듣기", "lv": 1, "n": 4, "t": "소리를 듣고 자음과 모음을 찾아요", "goal": "자음과 모음을 듣고 식별할 수 있어요.", "std": "자음과 모음을 듣고 식별할 수 있다.", "codes": "L-1-4-1, L-1-4-2", "theme": "한글 자모", "acts": ["낱말·표현 익히기: 아, 야, 드, 르", "모음(아, 야 등)을 말하면, 해당 모음을 고른다.", "자음의 음가(드,르 등)를 말하면, 해당 자음을 고른다.", "확인(진단형 L-1-4-1·L-1-4-2 섞기)"], "file": "lessons/g12-L-04.html", "st": "soon"}, {"id": "초1~2-듣기-05", "g": "초1~2", "a": "듣기", "lv": 2, "n": 5, "t": "친구의 부탁을 듣고 도와줘요", "goal": "교실에서 자주 사용하는 기초적인 대화 내용을 이해할 수 있어요.", "std": "교실에서 자주 사용하는 기초적인 대화 내용을 이해할 수 있다.", "codes": "L-2-1-1, L-2-1-2, L-2-1-3", "theme": "교실 대화", "acts": ["낱말·표현 익히기: 가위 주세요, 여기 있어요, 지금 어떤 도움이 필요하니?, 몇 학년 몇 반이에요?, 1학년 2반이에요, 기분이 어때요?", "도움을 요청하는 대화(가위 주세요./ 여기 있어요.등)를 듣고, 교사의 질문(지금 어떤 도움이 필요하니? 등)에 적절한 답을…", "정보를 묻는 대화(몇 학년 몇 반이에요? /1학년 2반이에요. 등)를 듣고, 안내된 정보를 고른다.", "확인(진단형) 감정을 나타내는 대화(기분이 어때요? /좋아요. 싫어요. 등)를 듣고, 적절한 감정 그림을 고른다."], "file": "lessons/g12-L-05.html", "st": "soon"}, {"id": "초1~2-듣기-06", "g": "초1~2", "a": "듣기", "lv": 2, "n": 6, "t": "선생님의 안내를 듣고 준비해요", "goal": "선생님의 안내를 듣고 필요한 준비물과 해야 할 일을 찾을 수 있어요.", "std": "수업에서 자주 쓰는 간단한 문장을 듣고 이해할 수 있다.", "codes": "L-2-2-1", "theme": "준비물", "acts": ["교실 물건 알아보기 — 그림을 눌러 이름을 들어요.", "필요한 준비물 찾기 — 짧은 안내에서 필요한 것을 골라요.", "여러 준비물을 한 번에 들어요 — 정보가 많아져도 필요한 것을 찾아요.", "들은 순서대로 행동하기 — 해야 할 일을 순서대로 놓아요."], "file": "lessons/g12-L-06.html", "st": "open"}, {"id": "초1~2-듣기-07", "g": "초1~2", "a": "듣기", "lv": 2, "n": 7, "t": "어디에 있는지 듣고 찾아요", "goal": "교실의 사물이나 대상에 관한 간단한 말을 듣고 이해할 수 있어요.", "std": "교실의 사물이나 대상에 관한 간단한 말을 듣고 이해할 수 있다.", "codes": "L-2-3-1, L-2-3-2", "theme": "위치·모양", "acts": ["낱말·표현 익히기: 창문 옆에 있어요, 빨간 가방, 큰 공책", "교실 사물의 위치(창문 옆에 있어요. 등)를 듣고, 해당 사물을 손가락으로 가리킨다.", "사물의 색깔이나 크기(빨간 가방, 큰 공책 등)를 듣고, 맞는 사물 그림을 고른다.", "확인(진단형 L-2-3-1·L-2-3-2 섞기)"], "file": "lessons/g12-L-07.html", "st": "soon"}, {"id": "초1~2-듣기-08", "g": "초1~2", "a": "듣기", "lv": 2, "n": 8, "t": "천천히 듣고 알맞은 그림을 골라요", "goal": "교사의 느린 발화를 듣고 이해할 수 있어요.", "std": "교사의 느린 발화를 듣고 이해할 수 있다.", "codes": "L-2-4-1, L-2-4-2, L-2-4-3", "theme": "학교 장소", "acts": ["낱말·표현 익히기: 보건실은 1층에 있어요, 지우개가 어디에 있어요?, 지우개, 한 줄로 서세요", "천천히 말한 문장(보건실은 1층에 있어요. 등)을 듣고, 문장과 맞는 그림을 고른다.", "천천히 말한 질문(지우개가 어디에 있어요? 등)을 듣고 해당 사물(지우개 등)을 가리킨다.", "확인(진단형) 천천히 말한 지시(한 줄로 서세요. 등)를 수행한다."], "file": "lessons/g12-L-08.html", "st": "soon"}, {"id": "초1~2-듣기-09", "g": "초1~2", "a": "듣기", "lv": 3, "n": 9, "t": "친구가 좋아하는 것을 알아봐요", "goal": "관심사(좋아하는 것 등)에 관한 대화를 듣고 짐작할 수 있어요.", "std": "관심사(좋아하는 것 등)에 관한 대화를 듣고 짐작할 수 있다.", "codes": "L-3-1-1, L-3-1-2, L-3-1-3", "theme": "좋아하는 것", "acts": ["낱말·표현 익히기: 공놀이, 줄넘기, 술래잡기, 김밥, 떡볶이, 불고기", "좋아하는 놀이(공놀이, 줄넘기, 술래잡기 등)에 관한 대화를 듣고, 하고 싶어 하는 놀이를 고른다.", "좋아하는 음식(김밥, 떡볶이, 불고기 등)에 관한 대화를 듣고, 먹고 싶어 하는 음식을 고른다.", "확인(진단형) 좋아하는 물건(인형, 장난감 등)에 관한 대화를 듣고, 갖고 싶어 하는 물건을 고른다."], "file": "lessons/g12-L-09.html", "st": "soon"}, {"id": "초1~2-듣기-10", "g": "초1~2", "a": "듣기", "lv": 3, "n": 10, "t": "주말 이야기를 듣고 장소를 찾아요", "goal": "겪은 일에 관한 이야기를 듣고 대강의 내용을 이해할 수 있어요.", "std": "겪은 일에 관한 이야기를 듣고 대강의 내용을 이해할 수 있다.", "codes": "L-3-2-1, L-3-2-2, L-3-2-3", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 주말 지낸 이야기, 공원, 학교, 집, 여행", "겪은 일에 관한 이야기(주말 지낸 이야기 등)를 듣고, 관련된 장소(공원, 학교, 집 등)를 고른다.", "겪은 일의 순서가 담긴 이야기(여행 등)를 듣고, 장소(공원, 학교, 집 등)를 이야기 순서대로 배열한다.", "확인(진단형) 겪은 일에 관한 이야기를 듣고, 일치하는 내용을 표시한다."], "file": "lessons/g12-L-10.html", "st": "soon"}, {"id": "초1~2-듣기-11", "g": "초1~2", "a": "듣기", "lv": 3, "n": 11, "t": "그림을 보며 방학 이야기를 들어요", "goal": "단서(그림 등)가 주어진 짧은 이야기를 듣고 내용을 이해할 수 있어요.", "std": "단서(그림 등)가 주어진 짧은 이야기를 듣고 내용을 이해할 수 있다.", "codes": "L-3-3-1, L-3-3-2", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 방학동안 한 일, 걸었다, 뛰었다, 방학 동안 한 일, 방학 동안 무엇을 했나요?", "그림을 보며 짧은 이야기(방학동안 한 일 등)를 듣고, 이야기 속 인물과 행동(걸었다, 뛰었다 등)을 연결한다.", "그림을 보며 짧은 이야기(방학 동안 한 일 등)를 듣고, 교사의 질문(방학 동안 무엇을 했나요? 등)에 알맞은 답을 한다.", "확인(진단형 L-3-3-1·L-3-3-2 섞기)"], "file": "lessons/g12-L-11.html", "st": "soon"}, {"id": "초1~2-듣기-12", "g": "초1~2", "a": "듣기", "lv": 3, "n": 12, "t": "선생님 설명에서 중요한 낱말을 찾아요", "goal": "교사의 발화를 듣고 내용을 부분적으로 이해할 수 있어요.", "std": "교사의 발화를 듣고 내용을 부분적으로 이해할 수 있다.", "codes": "L-3-4-1, L-3-4-2", "theme": "학교 행사", "acts": ["낱말·표현 익히기: 명절, 명절 놀이, 음식, 현장 체험 학습 준비물 안내, 준비물 중 모자, 도시락", "교사의 설명(명절 등)을 듣고, 중심 낱말(명절 놀이, 음식 등)을 답한다.", "교사의 안내(현장 체험 학습 준비물 안내 등)을 듣고, 중심 낱말(준비물 중 모자, 도시락 등)을 답한다.", "확인(진단형 L-3-4-1·L-3-4-2 섞기)"], "file": "lessons/g12-L-12.html", "st": "soon"}, {"id": "초1~2-듣기-13", "g": "초1~2", "a": "듣기", "lv": 4, "n": 13, "t": "친구 소개를 듣고 알아봐요", "goal": "친숙한 주제의 이야기를 듣고 대강의 내용을 이해할 수 있어요.", "std": "친숙한 주제의 이야기를 듣고 대강의 내용을 이해할 수 있다.", "codes": "L-4-1-1, L-4-1-2", "theme": "가족·소개", "acts": ["낱말·표현 익히기: 가족 소개, 방과후 활동, 장래희망", "친숙한 주제(가족 소개, 방과후 활동, 장래희망 등)의 이야기를 듣고, 이야기의 주제를 답한다.", "친숙한 주제(가족 소개, 방과후 활동, 장래희망 등)의 이야기를 듣고, 주요 정보를 답한다.", "확인(진단형 L-4-1-1·L-4-1-2 섞기)"], "file": "lessons/g12-L-13.html", "st": "soon"}, {"id": "초1~2-듣기-14", "g": "초1~2", "a": "듣기", "lv": 4, "n": 14, "t": "안내를 듣고 시간과 장소를 찾아요", "goal": "정보를 알리는 말을 듣고 주요 내용을 찾을 수 있어요.", "std": "정보를 알리는 말을 듣고 주요 내용을 찾을 수 있다.", "codes": "L-4-2-1, L-4-2-2, L-4-2-3", "theme": "학교 행사", "acts": ["낱말·표현 익히기: 2시에 도서관으로 오세요, 물감을 들고 오세요, 체육 대회, 시간, 장소, 내용", "안내 방송이나 교사의 알림(2시에 도서관으로 오세요. 등)을 듣고, 시간이나 장소를 답한다.", "준비물을 안내하는 말(물감을 들고 오세요. 등)을 듣고 준비해야 할 물건을 고른다.", "확인(진단형) 학교 행사 안내(체육 대회 등)를 듣고 그에 관한 정보(시간, 장소, 내용 등)를 답한다."], "file": "lessons/g12-L-14.html", "st": "soon"}, {"id": "초1~2-듣기-15", "g": "초1~2", "a": "듣기", "lv": 4, "n": 15, "t": "친구의 발표를 듣고 답해요", "goal": "이야기나 발표를 듣고 내용을 이해할 수 있어요.", "std": "이야기나 발표를 듣고 내용을 이해할 수 있다.", "codes": "L-4-3-1, L-4-3-2, L-4-3-3", "theme": "발표", "acts": ["낱말·표현 익히기: 내가 좋아하는 음식, 운동, 사람, 무엇에 관한 이야기인가요?", "이야기나 발표(내가 좋아하는 음식, 운동, 사람 등)를 듣고, 발표자가 소개한 대상을 보기에서 고른다.", "이야기나 발표(내가 좋아하는 음식, 운동, 사람 등)를 듣고, 발표 내용과 맞는 그림을 모두 고른다.", "확인(진단형) 이야기나 발표(내가 좋아하는 음식, 운동, 사람 등)를 듣고, 들은 내용에 대한 사실 질문(무엇에 관한 이…"], "file": "lessons/g12-L-15.html", "st": "soon"}, {"id": "초1~2-듣기-16", "g": "초1~2", "a": "듣기", "lv": 4, "n": 16, "t": "설명을 듣고 순서대로 해요", "goal": "교사의 발화를 듣고 주요 내용을 이해할 수 있어요.", "std": "교사의 발화를 듣고 주요 내용을 이해할 수 있다.", "codes": "L-4-4-1, L-4-4-2", "theme": "순서·과정", "acts": ["낱말·표현 익히기: 씨앗 심기 과정, 흙 담기, 씨앗 심기, 물 주기, 현장 체험 학습 주의 사항 안내, 장소 예절", "교사의 설명(씨앗 심기 과정 등)을 듣고, 일의 순서(흙 담기, 씨앗 심기, 물 주기 등)을 답한다.", "교사의 설명(현장 체험 학습 주의 사항 안내 등)을 듣고, 주요 내용(장소 예절, 안전 등)을 답한다.", "확인(진단형 L-4-4-1·L-4-4-2 섞기)"], "file": "lessons/g12-L-16.html", "st": "soon"}, {"id": "초1~2-말하기-01", "g": "초1~2", "a": "말하기", "lv": 1, "n": 1, "t": "교실 물건 이름을 말해요", "goal": "주변의 사물에 대해 짧고 쉬운 단어로 말할 수 있어요.", "std": "주변의 사물/대상에 대해 짧고 쉬운 단어로 말할 수 있다.", "codes": "S-1-1-1, S-1-1-2, S-1-1-3", "theme": "교실 물건", "acts": ["듣고 따라 말하기 — 선생님 소리를 듣고 따라 말해요.", "그림 보고 말하기 — 그림을 보고 이름을 말해요.", "묻는 말에 대답하기 — “이건 뭐예요?”에 대답해요.", "내 목소리 비교하기 — 내 목소리를 듣고 스스로 평가해요."], "file": "lessons/g12-S-01.html", "st": "open"}, {"id": "초1~2-말하기-02", "g": "초1~2", "a": "말하기", "lv": 1, "n": 2, "t": "친구와 어른에게 인사해요", "goal": "간단한 인사말을 주고받을 수 있어요.", "std": "간단한 인사말을 주고받을 수 있다.", "codes": "S-1-2-1, S-1-2-2", "theme": "인사", "acts": ["낱말·표현 익히기: 안녕, 잘가, 안녕하세요, 안녕히 계세요", "친구와 만나고 헤어질 때 인사말(안녕, 잘가. 등)을 한다.", "어른과 만나고 헤어질 때 인사말(안녕하세요, 안녕히 계세요. 등)을 한다.", "확인(진단형 S-1-2-1·S-1-2-2 섞기)"], "file": "lessons/g12-S-02.html", "st": "soon"}, {"id": "초1~2-말하기-03", "g": "초1~2", "a": "말하기", "lv": 1, "n": 3, "t": "이름과 나이를 말해요", "goal": "교사의 질문에 간단하게 대답할 수 있어요.", "std": "교사의 질문에 간단하게 대답할 수 있다.", "codes": "S-1-3-1, S-1-3-2, S-1-3-3", "theme": "자기소개", "acts": ["낱말·표현 익히기: 이름이 뭐예요?, 저는 ○○예요, 몇 살이예요?, 8, 여덟 살이에요, 이것은 뭐예요?", "이름을 묻는 질문(이름이 뭐예요? 등)에 자신의 이름(저는 ○○예요. 등)을 말한다.", "나이를 묻는 질문(몇 살이예요? 등)에 숫자나 짧은 문장(8, 여덟 살이에요. 등)으로 답한다.", "확인(진단형) 물건의 이름을 묻는 질문(이것은 뭐예요? 등) 에 한 단어(연필이에요. 등)로 답한다."], "file": "lessons/g12-S-03.html", "st": "soon"}, {"id": "초1~2-말하기-04", "g": "초1~2", "a": "말하기", "lv": 1, "n": 4, "t": "필요한 것을 말해요", "goal": "주요 단어로 의사를 표현할 수 있어요.", "std": "주요 단어로 의사를 표현할 수 있다.", "codes": "S-1-4-1, S-1-4-2, S-1-4-3", "theme": "도움 요청", "acts": ["낱말·표현 익히기: 물, 휴지, 그림, 놀자, 싫어요, 도와주세요", "활동 중 필요한 것이 있을 때, 그 이름(물, 휴지 등)을 말하여 요구한다.", "하고 싶은 활동을 한 단어나 짧은 구(그림, 놀자 등)로 말한다.", "확인(진단형) 싫거나 어려운 상황에서 거절이나 도움 요청 표현(싫어요, 도와주세요. 등)을 말한다."], "file": "lessons/g12-S-04.html", "st": "soon"}, {"id": "초1~2-말하기-05", "g": "초1~2", "a": "말하기", "lv": 1, "n": 5, "t": "천천히 또박또박 말해요", "goal": "부정확하지만 이해할 수 있는 발음과 속도로 천천히 말할 수 있어요.", "std": "부정확하지만 이해할 수 있는 발음과 속도로 천천히 말할 수 있다.", "codes": "S-1-5-1, S-1-5-2", "theme": "발음", "acts": ["낱말·표현 익히기: 핵심 낱말", "발음이 서툴러도 한음절씩 천천히 말한다.", "상대가 알아듣지 못했을 때 같은 말을 다시 천천히 말한다.", "확인(진단형 S-1-5-1·S-1-5-2 섞기)"], "file": "lessons/g12-S-05.html", "st": "soon"}, {"id": "초1~2-말하기-06", "g": "초1~2", "a": "말하기", "lv": 2, "n": 6, "t": "교실에서 자주 쓰는 말을 해요", "goal": "교실에서 자주 사용하는 문장으로 말할 수 있어요.", "std": "교실에서 자주 사용하는 문장으로 말할 수 있다.", "codes": "S-2-1-1, S-2-1-2, S-2-1-3", "theme": "교실 대화", "acts": ["낱말·표현 익히기: 화장실 가도 돼요?, 공책이 없어요", "교실에서 자주 사용하는 문장으로 말할 수 있다.", "교실 활동에서 허락을 구하는 문장(화장실 가도 돼요? 등)을 말한다.", "확인(진단형) 문제가 생겼을 때 교사에게 상황을 짧은 문장(공책이 없어요. 등)으로 말한다."], "file": "lessons/g12-S-06.html", "st": "soon"}, {"id": "초1~2-말하기-07", "g": "초1~2", "a": "말하기", "lv": 2, "n": 7, "t": "날씨와 좋아하는 것을 대답해요", "goal": "일상생활에서 자주 묻는 질문에 짧게 대답할 수 있어요.", "std": "일상생활에서 자주 묻는 질문에 짧게 대답할 수 있다.", "codes": "S-2-2-1, S-2-2-2, S-2-2-3", "theme": "좋아하는 것", "acts": ["낱말·표현 익히기: 오늘 날씨는 어때요?, 흐려요, 맑아요, 어떤 운동, 과일, 음식을 좋아해요?", "오늘의 날씨를 묻는 질문(오늘 날씨는 어때요? 등)에 짧은 문장(흐려요. 맑아요. 등)으로 답한다.", "좋아하는 것을 묻는 질문(어떤 운동/과일/음식을 좋아해요? 등)에 대상 이름(축구, 사과, 김밥 등)을 넣어 답한다.", "확인(진단형) 어디에 사는지 또는 어디에서 왔는지 묻는 질문(어디에 살아요? 등)에 짧게 답한다."], "file": "lessons/g12-S-07.html", "st": "soon"}, {"id": "초1~2-말하기-08", "g": "초1~2", "a": "말하기", "lv": 2, "n": 8, "t": "모르는 것을 물어봐요", "goal": "학교생활에서 간단한 정보를 요구하는 질문을 할 수 있어요.", "std": "학교생활에서 간단한 정보를 요구하는 질문을 할 수 있다.", "codes": "S-2-3-1, S-2-3-2, S-2-3-3, S-2-3-4", "theme": "준비물", "acts": ["낱말·표현 익히기: 어떻게 해요?, 색연필 어디 있어요?, 보건실이 어디에 있어요?, 이게 뭐예요? 몇 쪽이에요?", "활동 방법을 모를 때 방법을 묻는 질문(어떻게 해요? 등)을 한다.", "수업 준비물의 위치를 묻는 질문(색연필 어디 있어요? 등)을 한다.", "확인(진단형) 교실의 위치를 묻는 질문(보건실이 어디에 있어요? 등)을 한다."], "file": "lessons/g12-S-08.html", "st": "soon"}, {"id": "초1~2-말하기-09", "g": "초1~2", "a": "말하기", "lv": 2, "n": 9, "t": "내 마음을 한 문장으로 말해요", "goal": "간단한 문장으로 의사를 표현할 수 있어요.", "std": "간단한 문장으로 의사를 표현할 수 있다.", "codes": "S-2-4-1, S-2-4-2, S-2-4-3", "theme": "도움 요청", "acts": ["낱말·표현 익히기: 저는 우유가 좋아요, 공놀이를 하고 싶어요, 보건실에 가고 싶어요", "자신의 좋고 싫음을 한 문장(저는 우유가 좋아요. 등)으로 말한다.", "원하는 활동을 한 문장(공놀이를 하고 싶어요. 등)으로 말한다.", "확인(진단형) 도움이 필요한 상황을 한 문장(보건실에 가고 싶어요. 등)으로 말한다."], "file": "lessons/g12-S-09.html", "st": "soon"}, {"id": "초1~2-말하기-10", "g": "초1~2", "a": "말하기", "lv": 2, "n": 10, "t": "띄어서 분명하게 말해요", "goal": "부정확하지만 이해할 수 있는 발음과 속도로 말할 수 있어요.", "std": "부정확하지만 이해할 수 있는 발음과 속도로 말할 수 있다.", "codes": "S-2-5-1, S-2-5-2", "theme": "발음", "acts": ["낱말·표현 익히기: 이것은 내 가방이예요", "짧은 문장(이것은 내 가방이예요. 등)을 말할 때 낱말 사이를 자연스럽게 띄어 말한다.", "상대가 다시 물으면, 같은 말을 조금 더 분명한 발음과 속도로 다시 말한다.", "확인(진단형 S-2-5-1·S-2-5-2 섞기)"], "file": "lessons/g12-S-10.html", "st": "soon"}, {"id": "초1~2-말하기-11", "g": "초1~2", "a": "말하기", "lv": 3, "n": 11, "t": "좋아하는 것과 까닭을 말해요", "goal": "관심사(좋아하는 것 등)에 관해 말할 수 있어요.", "std": "관심사(좋아하는 것 등)에 관해 말할 수 있다.", "codes": "S-3-1-1, S-3-1-2, S-3-1-3", "theme": "좋아하는 것", "acts": ["낱말·표현 익히기: 딱지치기, 숨바꼭질, 실뜨기, 좋아하는 캐릭터, 게임, 취미", "좋아하는 놀이와 그 이유(딱지치기, 숨바꼭질, 실뜨기, 좋아하는 캐릭터, 게임, 취미, 영상 콘텐츠 등)에 관해 말한다.", "좋아하는 음식과 그 이유(짜장면은 맛있어요. 등)에 관해 말한다.", "확인(진단형) 좋아하는 계절과 그 이유(봄은 따뜻해서 좋아요. 등)에 관해 말한다."], "file": "lessons/g12-S-11.html", "st": "soon"}, {"id": "초1~2-말하기-12", "g": "초1~2", "a": "말하기", "lv": 3, "n": 12, "t": "주말에 한 일을 말해요", "goal": "일상생활에서 겪은 일에 관해 말할 수 있어요.", "std": "일상생활에서 겪은 일에 관해 말할 수 있다.", "codes": "S-3-2-1, S-3-2-2, S-3-2-3", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 가족 여행, 주말 지낸 이야기, 어제, 오늘", "겪은 일(가족 여행, 주말 지낸 이야기 등)을 시간 표현(어제, 오늘 등)을 사용해 말한다.", "겪은 일(가족 여행, 주말 지낸 이야기 등)에 나온 사람이나 장소를 포함해 말한다.", "확인(진단형) 겪은 일(가족 여행, 주말 지낸 이야기 등)에 대한 느낌을 한 문장으로 말한다."], "file": "lessons/g12-S-12.html", "st": "soon"}, {"id": "초1~2-말하기-13", "g": "초1~2", "a": "말하기", "lv": 3, "n": 13, "t": "수업 시간에 묻고 답해요", "goal": "수업에 참여하여 간단하게 질문하고 대답할 수 있어요.", "std": "수업에 참여하여 간단하게 질문하고 대답할 수 있다.", "codes": "S-3-3-1, S-3-3-2", "theme": "수업 참여", "acts": ["낱말·표현 익히기: 교과 어휘: 모양, 가구, 분리수거, 어떤 모양이 있나요?, 동그라미 모양이 있어요", "수업 내용 중 모르는 낱말(교과 어휘: 모양, 가구, 분리수거 등)을 질문한다.", "교사의 확인 질문(어떤 모양이 있나요? 등)에 수업 내용과 관련된 말(동그라미 모양이 있어요. 등)로 답한다.", "확인(진단형 S-3-3-1·S-3-3-2 섞기)"], "file": "lessons/g12-S-13.html", "st": "soon"}, {"id": "초1~2-말하기-14", "g": "초1~2", "a": "말하기", "lv": 3, "n": 14, "t": "친구와 짧게 이야기해요", "goal": "간단한 문장을 활용하여 짧은 대화에 참여할 수 있어요.", "std": "간단한 문장을 활용하여 짧은 대화에 참여할 수 있다.", "codes": "S-3-4-1, S-3-4-2", "theme": "좋아하는 것", "acts": ["낱말·표현 익히기: 딱지치기 할 줄 알아?, 나 할 줄 알아, 난 짜장면을 좋아해, 너는 뭘 좋아해?, 나는 김밥을 좋아해", "좋아하는 것에 관한 대화(딱지치기 할 줄 알아?/ 나 할 줄 알아. 등)를 한다.", "상대의 말(난 짜장면을 좋아해. 너는 뭘 좋아해? 등)을 듣고 그 말에 맞는 반응(나는 김밥을 좋아해. 등)을 한 문장으로 …", "확인(진단형 S-3-4-1·S-3-4-2 섞기)"], "file": "lessons/g12-S-14.html", "st": "soon"}, {"id": "초1~2-말하기-15", "g": "초1~2", "a": "말하기", "lv": 3, "n": 15, "t": "비슷한 소리를 구별해서 말해요", "goal": "비교적 정확한 발음으로 말할 수 있어요.", "std": "비교적 정확한 발음으로 말할 수 있다.", "codes": "S-3-5-1, S-3-5-2, S-3-5-3", "theme": "발음", "acts": ["낱말·표현 익히기: 발-팔, 볼-벌, 달-딸, 키가 크고 눈이 커요, 도서관에 가서 책을 읽어요", "제시한 낱말(발-팔, 볼-벌, 달-딸 등)을 구별되게 발음한다.", "문장을 말할 때 의미 단위로 끊어 말한다.(키가 크고 눈이 커요. , 도서관에 가서 책을 읽어요. 등)", "확인(진단형) 상대가 알아듣기 어려워하면 발음이나 속도를 고쳐 다시 말한다."], "file": "lessons/g12-S-15.html", "st": "soon"}, {"id": "초1~2-말하기-16", "g": "초1~2", "a": "말하기", "lv": 4, "n": 16, "t": "가족과 친구를 소개해요", "goal": "친숙한 주제에 관해 간단하게 말할 수 있어요.", "std": "친숙한 주제에 관해 간단하게 말할 수 있다.", "codes": "S-4-1-1, S-4-1-2", "theme": "가족·소개", "acts": ["낱말·표현 익히기: 가족 소개, 친구 소개, 방과후 활동, 장래희망, 운동 경기 사진, 장소 사진", "친숙한 주제(가족 소개, 친구 소개, 방과후 활동, 장래희망 등)에 관해 소개나 발표를 한다.", "그림이나 사진(운동 경기 사진, 장소 사진, 날씨 사진, 자연 사진 등)을 보며 관련된 정보를 두 가지 이상 말한다.", "확인(진단형 S-4-1-1·S-4-1-2 섞기)"], "file": "lessons/g12-S-16.html", "st": "soon"}, {"id": "초1~2-말하기-17", "g": "초1~2", "a": "말하기", "lv": 4, "n": 17, "t": "친구들에게 준비물을 알려 줘요", "goal": "친구들에게 정보를 알리는 말을 할 수 있어요.", "std": "친구들에게 정보를 알리는 말을 할 수 있다.", "codes": "S-4-2-1, S-4-2-2, S-4-2-3", "theme": "학교 행사", "acts": ["낱말·표현 익히기: 학급 활동, 운동회, 현장체험학습, 도시락, 물, 모자", "학교 생활(학급 활동, 운동회, 현장체험학습 등)에 필요한 준비물(도시락, 물, 모자, 필기 도구 등)을 친구에게 알린다.", "친구에게 학교 생활에 관한 내용(시간표, 식단표, 숙제 등)을 알린다.", "확인(진단형) 친구에게 일상생활에서 지켜야 할 내용(공공장소 예절, 학급 규칙, 교통 규칙 등)을 알린다."], "file": "lessons/g12-S-17.html", "st": "soon"}, {"id": "초1~2-말하기-18", "g": "초1~2", "a": "말하기", "lv": 4, "n": 18, "t": "내 생각을 발표해요", "goal": "수업에서 자신의 생각을 간단하게 말할 수 있어요.", "std": "수업에서 자신의 생각을 간단하게 말할 수 있다.", "codes": "S-4-3-1, S-4-3-2, S-4-3-3", "theme": "발표", "acts": ["낱말·표현 익히기: “제 생각은 ○○입니다.”, “왜냐하면 ○○이기 때문입니다.”, \"제 생각에 ○○이", "수업 주제에 대해 발표( “제 생각은 ○○입니다.” 등)의 형태로 자신의 생각을 말한다.", "이유나 근거를 들어 발표(“왜냐하면 ○○이기 때문입니다.” 등)의 형태로 자신의 생각을 말한다.", "확인(진단형) 그림이나 이야기 속 인물의 행동에 대해 자신의 생각(\"제 생각에 ○○이/가 거짓말을 말한 것은 나쁘다고 생…"], "file": "lessons/g12-S-18.html", "st": "soon"}, {"id": "초1~2-말하기-19", "g": "초1~2", "a": "말하기", "lv": 4, "n": 19, "t": "이야기를 주고받으며 대화해요", "goal": "다소 긴 대화에 자연스럽게 참여할 수 있어요.", "std": "다소 긴 대화에 자연스럽게 참여할 수 있다.", "codes": "S-4-4-1, S-4-4-2, S-4-4-3", "theme": "대화", "acts": ["낱말·표현 익히기: 자연 환경, 놀이, 명절, 수업, 맞아, 나도 그래", "주제(자연 환경, 놀이, 명절, 수업 등)에 관한 대화에서 질문과 대답을 두 차례 이상 주고받는다.", "상대의 말을 듣고 맞장구(맞아, 나도 그래. 등)나 확인 표현(정말 그랬어? 등)을 사용한다.", "확인(진단형) 대화 중 모르는 말을 들으면 되묻거나 설명(○○이 무슨 뜻이야? / ○○는 이런 뜻이야. 등)한다."], "file": "lessons/g12-S-19.html", "st": "soon"}, {"id": "초1~2-말하기-20", "g": "초1~2", "a": "말하기", "lv": 4, "n": 20, "t": "상대에 맞게 높임말을 써요", "goal": "대화 상대를 고려하여 어느 정도 자연스럽게 말할 수 있어요.", "std": "대화 상대를 고려하여 어느 정도 자연스럽게 말할 수 있다.", "codes": "S-4-5-1, S-4-5-2, S-4-5-3", "theme": "높임말", "acts": ["낱말·표현 익히기: “~주세요.”, “~해 주세요.”, \"괜찮아?, 같이 하자.\", 고마운 상황, 미안한 상황", "대상에 따라 높임말, 평어 (“~주세요.”, “~해 주세요.” , \"괜찮아?, 같이 하자.\" 등)을 사용하여 말한다.", "상황(고마운 상황, 미안한 상황 등)에 따라 알맞은 표현을 사용한다.", "확인(진단형) 발표나 대화에서 상대가 들을 수 있는 크기와 속도로 말한다."], "file": "lessons/g12-S-20.html", "st": "soon"}, {"id": "초1~2-읽기-01", "g": "초1~2", "a": "읽기", "lv": 1, "n": 1, "t": "글자와 낱말을 소리 내어 읽어요", "goal": "글자와 단어를 소리 내어 읽을 수 있어요.", "std": "글자와 단어를 소리 내어 읽을 수 있다.", "codes": "R-1-1-1, R-1-1-2, R-1-1-3", "theme": "한글 자모", "acts": ["글자 카드 읽기 — 글자를 눌러 소리를 듣고 따라 읽어요.", "소리 듣고 글자 찾기 — 들은 소리에 맞는 글자를 골라요.", "낱말과 그림 잇기 — 낱말을 읽고 알맞은 그림과 이어요.", "소리 내어 읽기 — 낱말을 읽으면서 녹음해요."], "file": "lessons/g12-R-01.html", "st": "open"}, {"id": "초1~2-읽기-02", "g": "초1~2", "a": "읽기", "lv": 1, "n": 2, "t": "낱말을 읽고 그림과 연결해요", "goal": "짧고 쉬운 단어를 읽고 의미를 이해할 수 있어요.", "std": "짧고 쉬운 단어를 읽고 의미를 이해할 수 있다.", "codes": "R-1-2-1, R-1-2-2", "theme": "교실 물건", "acts": ["낱말·표현 익히기: 가방, 우유, 강아지, 책상, 의자, 문", "낱말 카드(가방, 우유, 강아지 등)를 읽고 해당하는 그림이나 실물을 연결한다.", "교실 물건 이름(책상, 의자, 문 등)을 읽고 해당 물건에 사물 이름표를 붙인다.", "확인(진단형 R-1-2-1·R-1-2-2 섞기)"], "file": "lessons/g12-R-02.html", "st": "soon"}, {"id": "초1~2-읽기-03", "g": "초1~2", "a": "읽기", "lv": 1, "n": 3, "t": "학교 안내판을 읽어요", "goal": "생활에서 사용하는 간단한 안내/간판 등을 이해할 수 있어요.", "std": "생활에서 사용하는 간단한 안내/간판 등을 이해할 수 있다.", "codes": "R-1-3-1, R-1-3-2, R-1-3-3", "theme": "학교 장소", "acts": ["낱말·표현 익히기: 약국, 병원, 보건실, 화장실, 줄 서기, 손 씻기", "표지판, 간판에 쓰여진 어휘(약국, 병원, 보건실, 화장실 등)를 읽고 해당 장소를 가리키거나 이동한다.", "생활 규칙 안내(줄 서기, 손 씻기 등)를 읽고 해야 할 행동을 짧은 말이나 몸짓으로 나타낸다.", "확인(진단형) 신발장, 책상, 사물함 등에 붙은 이름표를 읽고 자신의 자리를 찾는다."], "file": "lessons/g12-R-03.html", "st": "soon"}, {"id": "초1~2-읽기-04", "g": "초1~2", "a": "읽기", "lv": 1, "n": 4, "t": "받침을 살펴 바르게 읽어요", "goal": "한글 자음과 모음, 받침 등 글자를 식별하여 읽을 수 있어요.", "std": "한글 자음과 모음, 받침 등 글자를 식별하여 읽을 수 있다.", "codes": "R-1-4-1, R-1-4-2, R-1-4-3", "theme": "한글 자모", "acts": ["낱말·표현 익히기: 오리, 우리 중 고르기, 사과, 자과 중 고르기, 물병, 문병 중 고르기", "그림(오리 등)을 보고 알맞은 모음(오리, 우리 중 고르기)이 들어간 글자를 골라 읽는다.", "그림(사과 등)을 보고 알맞은 자음(사과, 자과 중 고르기)이 들어간 글자를 골라 읽는다.", "확인(진단형) 그림(물병 등)을 보고 알맞은 받침(물병, 문병 중 고르기)이 들어간 글자를 골라 읽는다."], "file": "lessons/g12-R-04.html", "st": "soon"}, {"id": "초1~2-읽기-05", "g": "초1~2", "a": "읽기", "lv": 2, "n": 5, "t": "띄어서 문장을 읽어요", "goal": "문장을 알맞게 띄어 읽을 수 있어요.", "std": "문장을 알맞게 띄어 읽을 수 있다.", "codes": "R-2-1-1, R-2-1-2", "theme": "문장", "acts": ["낱말·표현 익히기: 나는 v 학교에 v 가요, 우유를 마셔요, 운동장에서 놀아요, 집에서 숙제를 해요", "표시한 쉬는 곳(나는 v 학교에 v 가요. 등)에 맞추어 짧은 문장을 띄어 읽는다.", "두세 어절로 된 짧은 문장(우유를 마셔요. 운동장에서 놀아요. 집에서 숙제를 해요. 등)을 낱말 사이에서 띄어 읽는다.", "확인(진단형 R-2-1-1·R-2-1-2 섞기)"], "file": "lessons/g12-R-05.html", "st": "soon"}, {"id": "초1~2-읽기-06", "g": "초1~2", "a": "읽기", "lv": 2, "n": 6, "t": "문장을 읽고 알맞게 행동해요", "goal": "문장의 의미를 대강 이해할 수 있어요.", "std": "문장의 의미를 대강 이해할 수 있다.", "codes": "R-2-2-1, R-2-2-2", "theme": "교실 지시", "acts": ["낱말·표현 익히기: 문을 닫아요, 문을 열어요, 고양이가 자요, 아이가 뛰어요, 민수가 공을 차요", "짧은 지시문(문을 닫아요. 문을 열어요. 등)을 읽고 문장에 맞는 행동을 한다.", "짧은 문장(고양이가 자요. 아이가 뛰어요. 민수가 공을 차요. 등)을 읽고 문장 내용과 맞는 그림을 연결한다.", "확인(진단형 R-2-2-1·R-2-2-2 섞기)"], "file": "lessons/g12-R-06.html", "st": "soon"}, {"id": "초1~2-읽기-07", "g": "초1~2", "a": "읽기", "lv": 2, "n": 7, "t": "알림장을 읽고 준비물을 찾아요", "goal": "알림장, 게시판 등의 글을 읽고 정보를 찾을 수 있어요.", "std": "알림장, 게시판 등의 글을 읽고 정보를 찾을 수 있다.", "codes": "R-2-3-1, R-2-3-2", "theme": "준비물", "acts": ["낱말·표현 익히기: 준비물: 색종이와 가위 가져오기, 색종이, 가위, 도서관에서 퀴즈 행사를 합니다, 장소, 일시", "알림장(준비물: 색종이와 가위 가져오기 등)을 읽고 필요한 준비물(색종이, 가위 등)을 고른다.", "게시판 안내문(도서관에서 퀴즈 행사를 합니다. 등)에서 필요한 정보(장소, 일시, 대상 등)에 동그라미를 한다.", "확인(진단형 R-2-3-1·R-2-3-2 섞기)"], "file": "lessons/g12-R-07.html", "st": "soon"}, {"id": "초1~2-읽기-08", "g": "초1~2", "a": "읽기", "lv": 2, "n": 8, "t": "뜻을 생각하며 끊어 읽어요", "goal": "문장을 의미 단위로 끊어 읽을 수 있어요.", "std": "문장을 의미 단위로 끊어 읽을 수 있다.", "codes": "R-2-4-1, R-2-4-2", "theme": "문장", "acts": ["낱말·표현 익히기: 지아가 v그림을 그려요, 운동장에서 v 친구와 놀아요, 아침에 v 학교에 가요", "누가 무엇을 하는지 드러나도록 짧은 문장(지아가 v그림을 그려요. 등)을 두 부분으로 나누어 읽는다.", "장소나 시간을 나타내는 말(운동장에서 v 친구와 놀아요. 아침에 v 학교에 가요. 등)을 앞부분에서 쉬어 읽는다.", "확인(진단형 R-2-4-1·R-2-4-2 섞기)"], "file": "lessons/g12-R-08.html", "st": "soon"}, {"id": "초1~2-읽기-09", "g": "초1~2", "a": "읽기", "lv": 3, "n": 9, "t": "짧은 글에서 누가, 어디에서를 찾아요", "goal": "쉽고 짧은 글을 읽고 대강의 내용을 이해할 수 있어요.", "std": "쉽고 짧은 글을 읽고 대강의 내용을 이해할 수 있다.", "codes": "R-3-1-1, R-3-1-2, R-3-1-3, R-3-1-4", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 핵심 낱말", "두세 문장으로 된 이야기를 읽고 등장인물을 표시한다.", "짧은 글을 읽고 일이 일어난 장소를 표시한다.", "확인(진단형) 짧은 글을 읽고 글에서 등장인물이 한 일을 고른다."], "file": "lessons/g12-R-09.html", "st": "soon"}, {"id": "초1~2-읽기-10", "g": "초1~2", "a": "읽기", "lv": 3, "n": 10, "t": "소개하는 글을 읽어요", "goal": "소개하는 글을 읽고 주요 내용을 찾을 수 있어요.", "std": "소개하는 글을 읽고 주요 내용을 찾을 수 있다.", "codes": "R-3-2-1, R-3-2-2, R-3-2-3", "theme": "가족·소개", "acts": ["낱말·표현 익히기: 옷차림, 생김새, 교화, 교목, 색깔, 다리 수", "친구 소개 글을 읽고 친구의 특징(옷차림, 생김새 등)에 알맞은 그림을 고른다.", "학교 소개 글을 읽고 주요 정보(교화, 교목 등)를 찾는다.", "확인(진단형) 좋아하는 동물 소개 글을 읽고 동물의 특징(색깔, 다리 수, 사는 곳 등)에 관한 질문에 답한다."], "file": "lessons/g12-R-10.html", "st": "soon"}, {"id": "초1~2-읽기-11", "g": "초1~2", "a": "읽기", "lv": 3, "n": 11, "t": "초대 글과 안내 글을 읽어요", "goal": "다양한 종류의 짧고 쉬운 글의 내용을 이해할 수 있어요.", "std": "다양한 종류의 짧고 쉬운 글의 내용을 이해할 수 있다.", "codes": "R-3-3-1, R-3-3-2, R-3-3-3, R-3-3-4", "theme": "학교 행사", "acts": ["낱말·표현 익히기: 도서관 이용방법, 학교 규칙, 생활문, 설명하는 글, 의견을 나타내는 글", "짧은 초대 글을 읽고 초대의 목적이나 의도를 찾아낸다.", "간단한 메세지를 읽고 부탁한 일을 문장으로 답한다.", "확인(진단형) 짧은 안내 글(도서관 이용방법, 학교 규칙 등)을 읽고 해야 할 행동을 찾는다."], "file": "lessons/g12-R-11.html", "st": "soon"}, {"id": "초1~2-읽기-12", "g": "초1~2", "a": "읽기", "lv": 3, "n": 12, "t": "문단에서 중심 내용을 찾아요", "goal": "다양한 구조의 문장으로 이루어진 문단을 읽고 중심 내용을 이해할 수 있어요.", "std": "다양한 구조의 문장으로 이루어진 문단을 읽고 중심 내용을 이해할 수 있다.", "codes": "R-3-4-1, R-3-4-2, R-3-4-3", "theme": "중심 내용", "acts": ["낱말·표현 익히기: 핵심 낱말", "짧은 문단을 읽고 무엇에 대한 글인지 한 단어나 짧은 말로 말한다.", "짧은 문단을 읽고 까닭이나 결과를 나타내는 문장을 고른다. 원인과 결과가 드러나는 문장", "확인(진단형) 짧은 문단을 읽고 주제와 관련 없는 그림이나 문장을 고른다."], "file": "lessons/g12-R-12.html", "st": "soon"}, {"id": "초1~2-읽기-13", "g": "초1~2", "a": "읽기", "lv": 4, "n": 13, "t": "글을 읽고 일의 순서를 알아요", "goal": "쉽고 짧은 글을 읽고 전반적인 내용을 이해할 수 있어요.", "std": "쉽고 짧은 글을 읽고 전반적인 내용을 이해할 수 있다.", "codes": "R-4-1-1, R-4-1-2, R-4-1-3, R-4-1-4", "theme": "순서·과정", "acts": ["낱말·표현 익히기: 인물을 설명하는 글, 여행을 다녀온 글, 요리방법을 설명하는 글, 하루 일과, 놀이 방법, 일기", "짧은 글(인물을 설명하는 글, 여행을 다녀온 글 등)을 읽고 누가, 어디에서, 무엇을 했는지 각각 표시한다.", "짧은 글(요리방법을 설명하는 글, 하루 일과, 놀이 방법 등)을 읽고 일의 순서대로 그림 카드로 나타낸다.", "확인(진단형) 짧은 글을 읽고 내용과 맞는 문장에 동그라미를 한다."], "file": "lessons/g12-R-13.html", "st": "soon"}, {"id": "초1~2-읽기-14", "g": "초1~2", "a": "읽기", "lv": 4, "n": 14, "t": "옛이야기를 읽고 줄거리를 알아요", "goal": "이야기를 읽고 줄거리를 이해할 수 있어요.", "std": "이야기를 읽고 줄거리를 이해할 수 있다.", "codes": "R-4-2-1, R-4-2-2, R-4-2-3", "theme": "이야기", "acts": ["낱말·표현 익히기: 전래 동화, 이솝 우화", "이야기(전래 동화, 이솝 우화 등)를 읽고 문장 카드를 일이 일어난 순서대로 놓는다.", "이야기(전래 동화, 이솝 우화 등)를 읽고 등장인물에게 생긴 일이 나타난 문장을 찾는다.", "확인(진단형) 이야기(전래 동화, 이솝 우화 등)를 읽고 줄거리와 관련 없는 문장을 고른다."], "file": "lessons/g12-R-14.html", "st": "soon"}, {"id": "초1~2-읽기-15", "g": "초1~2", "a": "읽기", "lv": 4, "n": 15, "t": "교과서 글을 읽고 이해해요", "goal": "교과서에 나오는 글의 내용을 이해할 수 있어요.", "std": "교과서에 나오는 글의 내용을 이해할 수 있다.", "codes": "R-4-3-1, R-4-3-2, R-4-3-3, R-4-3-4", "theme": "교과서", "acts": ["낱말·표현 익히기: 핵심 낱말", "교과서의 짧은 설명 글을 읽고, 글에서 설명하는 대상을 고른다.", "교과서의 짧은 이야기 글을 읽고, 누가 무엇을 했는지 찾는다.", "확인(진단형) 교과서 글에 있는 그림을 보고 글과 관련된 정보를 고른다."], "file": "lessons/g12-R-15.html", "st": "soon"}, {"id": "초1~2-읽기-16", "g": "초1~2", "a": "읽기", "lv": 4, "n": 16, "t": "글에 어울리는 제목을 골라요", "goal": "글을 읽고 중심 내용을 이해할 수 있어요.", "std": "글을 읽고 중심 내용을 이해할 수 있다.", "codes": "R-4-4-1, R-4-4-2, R-4-4-3", "theme": "중심 내용", "acts": ["낱말·표현 익히기: 생활문, 설명하는 글, 의견을 나타내는 글", "글(생활문, 설명하는 글, 의견을 나타내는 글 등)을 읽고 글에 가장 어울리는 제목을 고른다.", "글(생활문, 설명하는 글, 의견을 나타내는 글 등)을 읽고 주제와 관련된 낱말에 표시한다.", "확인(진단형) 글(생활문, 설명하는 글, 의견을 나타내는 글 등)을 읽고 중심 내용과 맞는 문장을 보기에서 고른다."], "file": "lessons/g12-R-16.html", "st": "soon"}, {"id": "초1~2-쓰기-01", "g": "초1~2", "a": "쓰기", "lv": 1, "n": 1, "t": "글자와 낱말을 따라 써요", "goal": "글자와 단어를 쓸 수 있어요.", "std": "글자와 단어를 쓸 수 있다.", "codes": "W-1-1-1, W-1-1-2, W-1-1-3", "theme": "한글 자모", "acts": ["글자 보고 소리 듣기 — 써 볼 글자와 낱말을 살펴봐요.", "글자 따라 쓰기 — 흐린 글자 위에 따라 써요.", "낱말 따라 쓰기 — 흐린 낱말 위에 따라 써요.", "혼자 써 보기 — 보고 혼자 쓴 뒤 바른 글자와 비교해요."], "file": "lessons/g12-W-01.html", "st": "open"}, {"id": "초1~2-쓰기-02", "g": "초1~2", "a": "쓰기", "lv": 1, "n": 2, "t": "획순에 맞게 글자를 써요", "goal": "필순과 자형에 맞게 글자를 쓸 수 있어요.", "std": "필순과 자형에 맞게 글자를 쓸 수 있다.", "codes": "W-1-2-1, W-1-2-2", "theme": "한글 자모", "acts": ["낱말·표현 익히기: 라, 모, 부, 차, 커, 트", "글자(라, 모, 부. 차, 커, 트, 해 등)의 획을 차례대로 따라 쓴다.", "글자(사, 우, 교 등)를 자형에 맞게 쓴다.", "확인(진단형 W-1-2-1·W-1-2-2 섞기)"], "file": "lessons/g12-W-02.html", "st": "soon"}, {"id": "초1~2-쓰기-03", "g": "초1~2", "a": "쓰기", "lv": 1, "n": 3, "t": "내 이름과 나이를 써요", "goal": "인사말이나 간단한 신상 정보(이름, 나이 등)를 쓸 수 있어요.", "std": "인사말이나 간단한 신상 정보(이름, 나이 등)를 쓸 수 있다.", "codes": "W-1-3-1, W-1-3-2, W-1-3-3", "theme": "자기소개", "acts": ["낱말·표현 익히기: 8, 여덟 살, 1, 1학년", "자기 이름을 쓴다.", "나이(8, 여덟 살 등)나 학년(1, 1학년 등)을 숫자와 낱말로 쓴다.", "확인(진단형) 간단한 인사말을 보고 따라 쓴다."], "file": "lessons/g12-W-03.html", "st": "soon"}, {"id": "초1~2-쓰기-04", "g": "초1~2", "a": "쓰기", "lv": 1, "n": 4, "t": "그림을 보고 낱말을 써요", "goal": "단순한 시각 자료를 보고 해당하는 단어를 쓸 수 있어요.", "std": "단순한 시각 자료를 보고 해당하는 단어를 쓸 수 있다.", "codes": "W-1-4-1", "theme": "교실 물건", "acts": ["낱말·표현 익히기: 그림, 사진, 스티커, 공, 책, 사과", "시각 자료(그림, 사진, 스티커 등)을 보고 알맞은 낱말(공, 책, 사과 등)을 쓴다.", "같은 방식, 소재를 바꿔 한 번 더", "확인(진단형 W-1-4-1)"], "file": "lessons/g12-W-04.html", "st": "soon"}, {"id": "초1~2-쓰기-05", "g": "초1~2", "a": "쓰기", "lv": 2, "n": 5, "t": "그림을 보고 짧은 문장을 써요", "goal": "단어와 짧은 문장을 쓸 수 있어요.", "std": "단어와 짧은 문장을 쓸 수 있다.", "codes": "W-2-1-1, W-2-1-2, W-2-1-3", "theme": "문장", "acts": ["낱말·표현 익히기: 물을 마시는 모습, 물, 마셔요, 물을 마셔요, 'OO이, 가 있어요'", "그림(물을 마시는 모습 등)에 맞는 낱말(물, 마셔요. 등)을 넣어 짧은 문장(물을 마셔요. 등)을 완성한다.", "교실 물건을 보고 ('OO이/가 있어요' 등) 문장으로 쓴다.", "확인(진단형) 사람이나 동물이 하는 일을 짧은 문장(고양이가 자요. 그림을 그려요. 등)으로 쓴다."], "file": "lessons/g12-W-05.html", "st": "soon"}, {"id": "초1~2-쓰기-06", "g": "초1~2", "a": "쓰기", "lv": 2, "n": 6, "t": "듣고 받아써요", "goal": "소리와 표기의 차이를 알고 단어의 받아쓰기를 할 수 있어요.", "std": "소리와 표기의 차이를 알고 단어의 받아쓰기를 할 수 있다.", "codes": "W-2-2-1, W-2-2-2", "theme": "받아쓰기", "acts": ["낱말·표현 익히기: 줄넘기, 문어, 앉다, 안다, 빛, 빗", "천천히 읽어 주는 익숙한 낱말(줄넘기, 문어 등)을 듣고 실제 표기에 맞는 글자로 받아쓴다.", "그림을 보고 받침이 있는 짧은 낱말(앉다/안다, 빛/빗, 입/잎 등)을 듣고 뜻에 맞는 글자로 구별하여 받아쓴다.", "확인(진단형 W-2-2-1·W-2-2-2 섞기)"], "file": "lessons/g12-W-06.html", "st": "soon"}, {"id": "초1~2-쓰기-07", "g": "초1~2", "a": "쓰기", "lv": 2, "n": 7, "t": "겪은 일을 한 문장으로 써요", "goal": "겪은 일을 짧은 문장으로 쓸 수 있어요.", "std": "겪은 일을 짧은 문장으로 쓸 수 있다.", "codes": "W-2-3-1", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 수영하는 사진, 축구하는 사진, 수영을 했어요, 축구를 했어요", "사진 또는 그림(수영하는 사진, 축구하는 사진 등)을 보고 겪은 일에 관해 한 문장(수영을 했어요. 축구를 했어요. 등)으로…", "같은 방식, 소재를 바꿔 한 번 더", "확인(진단형 W-2-3-1)"], "file": "lessons/g12-W-07.html", "st": "soon"}, {"id": "초1~2-쓰기-08", "g": "초1~2", "a": "쓰기", "lv": 2, "n": 8, "t": "준비물과 할 일을 메모해요", "goal": "생활에 필요한 간단한 메모를 할 수 있어요.", "std": "생활에 필요한 간단한 메모를 할 수 있다.", "codes": "W-2-4-1, W-2-4-2", "theme": "준비물", "acts": ["낱말·표현 익히기: 그림, 사진, 스티커, 줄넘기, 운동화, 모자", "시각 자료(그림, 사진, 스티커 등)를 보고 필요한 준비물(줄넘기, 운동화, 모자, 물 등)을 쓴다.", "시각 자료(그림, 사진, 스티커 등)를 보고 숙제나 해야 할 일을 한 문장(숙제를 해요. 피아노를 쳐요. 물건을 사요. 등)…", "확인(진단형 W-2-4-1·W-2-4-2 섞기)"], "file": "lessons/g12-W-08.html", "st": "soon"}, {"id": "초1~2-쓰기-09", "g": "초1~2", "a": "쓰기", "lv": 3, "n": 9, "t": "까닭을 넣어 문장을 써요", "goal": "다양한 구조의 문장을 쓸 수 있어요.", "std": "다양한 구조의 문장을 쓸 수 있다.", "codes": "W-3-1-1, W-3-1-2, W-3-1-3, W-3-1-4", "theme": "좋아하는 것", "acts": ["낱말·표현 익히기: 아기가 웃어요, 교실에서 공부해요, 축구가 재미있어서 좋아요, 밥을 먹고 물을 마셔요", "대상과 특징을 넣어 한 문장(아기가 웃어요. 등)으로 쓴다.", "장소를 나타내는 말을 넣어 한 문장(교실에서 공부해요. 등)으로 쓴다.", "확인(진단형) 좋아하는 것과 까닭을 넣어 한 문장(축구가 재미있어서 좋아요. 등)으로 쓴다."], "file": "lessons/g12-W-09.html", "st": "soon"}, {"id": "초1~2-쓰기-10", "g": "초1~2", "a": "쓰기", "lv": 3, "n": 10, "t": "문장부호를 바르게 써요", "goal": "어느 정도 어법에 맞게 단어나 문장을 쓸 수 있어요.", "std": "어느 정도 어법에 맞게 단어나 문장을 쓸 수 있다.", "codes": "W-3-2-1, W-3-2-2", "theme": "문장", "acts": ["낱말·표현 익히기: 마침표, 물음표, 느낌표", "주어진 두 가지 이상의 낱말을 자연스럽게 이어 문장을 만든다.", "문장이 끝나는 곳에 문장부호(마침표, 물음표, 느낌표 등)를 표시한다.", "확인(진단형 W-3-2-1·W-3-2-2 섞기)"], "file": "lessons/g12-W-10.html", "st": "soon"}, {"id": "초1~2-쓰기-11", "g": "초1~2", "a": "쓰기", "lv": 3, "n": 11, "t": "마음을 전하는 글을 써요", "goal": "소개하거나 마음을 전하는 글을 쓸 수 있어요.", "std": "소개하거나 마음을 전하는 글을 쓸 수 있다.", "codes": "W-3-3-1, W-3-3-2, W-3-3-3, W-3-3-4", "theme": "마음 전하기", "acts": ["낱말·표현 익히기: 핵심 낱말", "자신을 소개하는 짧은 문단을 쓴다.", "친구나 가족을 소개하는 짧은 문단을 쓴다.", "확인(진단형) 고마운 마음을 전하는 짧은 문단을 쓴다."], "file": "lessons/g12-W-11.html", "st": "soon"}, {"id": "초1~2-쓰기-12", "g": "초1~2", "a": "쓰기", "lv": 3, "n": 12, "t": "내 생각을 한 문장으로 써요", "goal": "간단하게 자신의 생각을 문장으로 쓸 수 있어요.", "std": "간단하게 자신의 생각을 문장으로 쓸 수 있다.", "codes": "W-3-4-1, W-3-4-2", "theme": "생각 표현", "acts": ["낱말·표현 익히기: 저는 태극기라고 생각합니다, 저는 앞으로 ~게 하겠습니다", "질문(한국에 대해 배운 후 \"한국을 나타내는 것은 무엇일까요? 등)에 대해 (저는 태극기라고 생각합니다. 등) 형태로 쓴다.", "자신의 다짐과 생각을 쉬운 표현으로 한 문장(저는 앞으로 ~게 하겠습니다. 등)으로 쓴다.", "확인(진단형 W-3-4-1·W-3-4-2 섞기)"], "file": "lessons/g12-W-12.html", "st": "soon"}, {"id": "초1~2-쓰기-13", "g": "초1~2", "a": "쓰기", "lv": 4, "n": 13, "t": "주제에 맞게 두세 문장을 써요", "goal": "주제가 드러나게 짧은 글을 쓸 수 있어요.", "std": "주제가 드러나게 짧은 글을 쓸 수 있다.", "codes": "W-4-1-1", "theme": "주제 글쓰기", "acts": ["낱말·표현 익히기: 우리 주변 사람들, 우리 마을", "정해진 주제(우리 주변 사람들, 우리 마을 등)에서 벗어나지 않고 두세 문장으로 쓴다.", "같은 방식, 소재를 바꿔 한 번 더", "확인(진단형 W-4-1-1)"], "file": "lessons/g12-W-13.html", "st": "soon"}, {"id": "초1~2-쓰기-14", "g": "초1~2", "a": "쓰기", "lv": 4, "n": 14, "t": "띄어쓰기와 조사를 바르게 써요", "goal": "비교적 어법에 맞게 단어나 문장을 쓸 수 있어요.", "std": "비교적 어법에 맞게 단어나 문장을 쓸 수 있다.", "codes": "W-4-2-1, W-4-2-2", "theme": "문장", "acts": ["낱말·표현 익히기: 연결어, 조사 포함: 은, 는, 이, 가", "낱말을 자연스럽게 이어 문장을 만든다. (연결어, 조사 포함: 은/는/이/가, -고, -한 후에 등)", "문장을 알맞게 띄어 쓴다.", "확인(진단형 W-4-2-1·W-4-2-2 섞기)"], "file": "lessons/g12-W-14.html", "st": "soon"}, {"id": "초1~2-쓰기-15", "g": "초1~2", "a": "쓰기", "lv": 4, "n": 15, "t": "그림일기를 써요", "goal": "자신의 경험과 감정이 드러나게 일기를 쓸 수 있어요.", "std": "자신의 경험과 감정이 드러나게 일기를 쓸 수 있다.", "codes": "W-4-3-1, W-4-3-2", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 설레다, 기대되다, 즐겁다, 부끄럽다, 걱정이 되다, 속상하다", "오늘 또는 최근에 자신이 겪은 일을 두세 문장으로 쓴다.", "기분을 나타내는 말(설레다. 기대되다. 즐겁다. 부끄럽다. 걱정이 되다. 속상하다. 놀라다. 등)을 사용하여 일기를 쓴다.", "확인(진단형 W-4-3-1·W-4-3-2 섞기)"], "file": "lessons/g12-W-15.html", "st": "soon"}, {"id": "초1~2-쓰기-16", "g": "초1~2", "a": "쓰기", "lv": 4, "n": 16, "t": "배운 내용을 정리해서 써요", "goal": "수업과 관련된 내용을 여러 문장으로 쓸 수 있어요.", "std": "수업과 관련된 내용을 여러 문장으로 쓸 수 있다.", "codes": "W-4-4-1, W-4-4-2", "theme": "수업 정리", "acts": ["낱말·표현 익히기: 태극기는 한국을 나타냅니다, 무궁화도 있습니다, 교통 안전, 생활 안전, 재난 안전", "질문(한국에 대해 배운 후 \"한국을 나타내는 것은 무엇일까요? 등)에 대해 두세 문장(태극기는 한국을 나타냅니다. 무궁화도 …", "수업 활동(교통 안전, 생활 안전, 재난 안전 등) 후 알게 된 점이나 느낀 점을 두세 문장으로 쓴다.", "확인(진단형 W-4-4-1·W-4-4-2 섞기)"], "file": "lessons/g12-W-16.html", "st": "soon"}, {"id": "초3~4-듣기-01", "g": "초3~4", "a": "듣기", "lv": 1, "n": 1, "t": "물건 이름을 듣고 찾아요", "goal": "짧고 쉬운 단어를 듣고 대상을 찾을 수 있어요.", "std": "짧고 쉬운 단어를 듣고 대상을 찾을 수 있다.", "codes": "L-1-1-1, L-1-1-2, L-1-1-3", "theme": "교실 물건", "acts": ["낱말·표현 익히기: 연필, 지우개, 공책, 사과, 포도, 우유", "교실 사물(연필, 지우개, 공책 등의 학용품 등)을 말하면, 해당 사물을 가리킨다.", "음식 이름(사과, 포도, 우유 등)을 말하면, 해당 사물을 가리킨다.", "확인(진단형) 생활 용품(모자, 가방, 책상, 의자 등)을 말하면, 해당 사물을 가리킨다."], "file": "lessons/g34-L-01.html", "st": "soon"}, {"id": "초3~4-듣기-02", "g": "초3~4", "a": "듣기", "lv": 1, "n": 2, "t": "만나고 헤어질 때 인사해요", "goal": "간단한 인사말을 듣고 이해할 수 있어요.", "std": "간단한 인사말을 듣고 이해할 수 있다.", "codes": "L-1-2-1, L-1-2-2", "theme": "인사", "acts": ["낱말·표현 익히기: 안녕하세요, 안녕히 계세요, 안녕히 가세요, 내일 봐요", "만나고 헤어질 때 인사말(안녕하세요, 안녕히 계세요 등)에 답한다.", "만나고 헤어질 때 인사말(안녕히 가세요, 내일 봐요. 등)에 알맞은 표정이나 몸짓으로 반응한다.", "확인(진단형 L-1-2-1·L-1-2-2 섞기)"], "file": "lessons/g34-L-02.html", "st": "soon"}, {"id": "초3~4-듣기-03", "g": "초3~4", "a": "듣기", "lv": 1, "n": 3, "t": "교실 지시를 듣고 행동해요", "goal": "교실에서 사용하는 지시를 듣고 따를 수 있어요.", "std": "교실에서 사용하는 지시를 듣고 따를 수 있다.", "codes": "L-1-3-1, L-1-3-2", "theme": "교실 지시", "acts": ["낱말·표현 익히기: 준비물을 꺼내세요, 자리에 앉으세요, 오른손을 드세요, 앞으로 나오세요", "교실에서 사용하는 지시(준비물을 꺼내세요, 자리에 앉으세요. 등)를 듣고 해당 행동을 수행한다.", "교실에서 방향을 포함한 지시(오른손을 드세요. 앞으로 나오세요. 등)를 듣고, 해당 행동을 수행한다.", "확인(진단형 L-1-3-1·L-1-3-2 섞기)"], "file": "lessons/g34-L-03.html", "st": "soon"}, {"id": "초3~4-듣기-04", "g": "초3~4", "a": "듣기", "lv": 1, "n": 4, "t": "낱말을 듣고 그림을 찾아요", "goal": "소리를 듣고 단어를 식별할 수 있어요.", "std": "소리를 듣고 단어를 식별할 수 있다.", "codes": "L-1-4-1", "theme": "학교 장소", "acts": ["낱말·표현 익히기: 체육관, 보건실, 줄넘기, 물병", "낱말(체육관, 보건실, 줄넘기, 물병 등)을 듣고 해당 그림이나 실물을 손가락으로 가리킨다.", "같은 방식, 소재를 바꿔 한 번 더", "확인(진단형 L-1-4-1)"], "file": "lessons/g34-L-04.html", "st": "soon"}, {"id": "초3~4-듣기-05", "g": "초3~4", "a": "듣기", "lv": 2, "n": 5, "t": "묻고 답하는 대화를 들어요", "goal": "일상과 학교생활에서 자주 사용하는 기초적인 대화 내용을 파악할 수 있어요.", "std": "일상과 학교생활에서 자주 사용하는 기초적인 대화 내용을 파악할 수 있다.", "codes": "L-2-1-1, L-2-1-2, L-2-1-3", "theme": "생활 대화", "acts": ["낱말·표현 익히기: 마트가 어디에 있어요?, 마트는 꽃집 옆에 있어요, 화장실은 어디에 있어요?, 화장실은 공원 안에 있어요, 어디에 가요? 마트는 어디에 있어요?, 이건 얼마예요?", "도움을 요청하는 대화(마트가 어디에 있어요? / 마트는 꽃집 옆에 있어요. , 화장실은 어디에 있어요? / 화장실은 공원 안…", "정보를 묻는 대화(이건 얼마예요?, 지금 몇 시예요? 등)를 듣고, 안내된 정보를 고른다.", "확인(진단형) 감정을 나타내는 대화(기분이 어때요? / 좋아요. 싫어요. 즐거워요. 화가 나요. 등)를 듣고, 적절한 감…"], "file": "lessons/g34-L-05.html", "st": "soon"}, {"id": "초3~4-듣기-06", "g": "초3~4", "a": "듣기", "lv": 2, "n": 6, "t": "선생님의 안내를 듣고 준비해요", "goal": "선생님의 안내를 듣고 필요한 준비물과 해야 할 일을 찾을 수 있어요.", "std": "수업에서 자주 쓰는 문장을 듣고 파악할 수 있다.", "codes": "L-2-2-1", "theme": "준비물", "acts": ["교실 물건 알아보기 — 그림을 눌러 이름을 들어요.", "필요한 준비물 찾기 — 짧은 안내에서 필요한 것을 골라요.", "여러 준비물을 한 번에 들어요 — 정보가 많아져도 필요한 것을 찾아요.", "들은 순서대로 행동하기 — 해야 할 일을 순서대로 놓아요."], "file": "lessons/g34-L-06.html", "st": "open"}, {"id": "초3~4-듣기-07", "g": "초3~4", "a": "듣기", "lv": 2, "n": 7, "t": "위치와 모양을 듣고 찾아요", "goal": "주변의 사물과 대상에 관한 간단한 말을 듣고 파악할 수 있어요.", "std": "주변의 사물과 대상에 관한 간단한 말을 듣고 파악할 수 있다.", "codes": "L-2-3-1, L-2-3-2", "theme": "위치·모양", "acts": ["낱말·표현 익히기: 의자 옆에 피아노가 있어요, 높은 의자, 파란 자동차", "주변 사물의 위치(의자 옆에 피아노가 있어요. 등)를 듣고, 알맞은 그림을 손가락으로 가리킨다.", "주변 사물의 색깔이나 크기(높은 의자, 파란 자동차 등)를 듣고, 맞는 사물 그림을 고른다.", "확인(진단형 L-2-3-1·L-2-3-2 섞기)"], "file": "lessons/g34-L-07.html", "st": "soon"}, {"id": "초3~4-듣기-08", "g": "초3~4", "a": "듣기", "lv": 2, "n": 8, "t": "천천히 듣고 질문에 답해요", "goal": "교사의 느린 발화를 듣고 이해할 수 있어요.", "std": "교사의 느린 발화를 듣고 이해할 수 있다.", "codes": "L-2-4-1, L-2-4-2, L-2-4-3", "theme": "생활 대화", "acts": ["낱말·표현 익히기: 가방 안에 크레파스와 색연필이 있어요, 오늘은 무슨 요일이예요?, 바른 자세로 앉으세요, 부모님께 보여 드리세요, 큰 소리로 말하세요", "천천히 말한 문장(가방 안에 크레파스와 색연필이 있어요. 등)을 듣고, 문장과 맞는 그림을 고른다.", "천천히 말한 질문(오늘은 무슨 요일이예요? 등)을 듣고 답한다.", "확인(진단형) 천천히 말한 지시(바른 자세로 앉으세요. 부모님께 보여 드리세요. 큰 소리로 말하세요. 등)를 수행한다."], "file": "lessons/g34-L-08.html", "st": "soon"}, {"id": "초3~4-듣기-09", "g": "초3~4", "a": "듣기", "lv": 3, "n": 9, "t": "체험학습과 생일 초대 이야기를 들어요", "goal": "친숙한 주제에 관한 대화를 듣고 내용을 짐작할 수 있어요.", "std": "친숙한 주제에 관한 대화를 듣고 내용을 짐작할 수 있다.", "codes": "L-3-1-1, L-3-1-2", "theme": "학교 행사", "acts": ["낱말·표현 익히기: 현장체험학습 장소, 방과후 활동, 생일초대", "친숙한 주제(현장체험학습 장소, 방과후 활동, 생일초대 등)의 이야기를 듣고, 질문에 알맞게 답한다.", "친숙한 주제(현장체험학습 장소, 방과후 활동, 생일초대 등)의 이야기를 듣고, 주요 정보를 고른다.", "확인(진단형 L-3-1-1·L-3-1-2 섞기)"], "file": "lessons/g34-L-09.html", "st": "soon"}, {"id": "초3~4-듣기-10", "g": "초3~4", "a": "듣기", "lv": 3, "n": 10, "t": "겪은 일을 듣고 순서대로 놓아요", "goal": "겪은 일에 관한 이야기를 듣고 대강의 내용을 파악할 수 있어요.", "std": "겪은 일에 관한 이야기를 듣고 대강의 내용을 파악할 수 있다.", "codes": "L-3-2-1, L-3-2-2, L-3-2-3", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 주말 지낸 이야기, 공원, 학교, 집, 여행", "겪은 일에 관한 이야기(주말 지낸 이야기 등)를 듣고, 관련된 장소(공원, 학교, 집 등)를 고른다.", "겪은 일의 순서가 담긴 이야기(여행 등)를 듣고, 장소(공원, 학교, 집 등)를 이야기 순서대로 배열한다.", "확인(진단형) 겪은 일에 관한 이야기를 듣고, 일치하는 내용을 표시한다."], "file": "lessons/g34-L-10.html", "st": "soon"}, {"id": "초3~4-듣기-11", "g": "초3~4", "a": "듣기", "lv": 3, "n": 11, "t": "그림을 보며 계획 이야기를 들어요", "goal": "단서(그림 등)가 주어진 짧은 이야기를 듣고 내용을 파악할 수 있어요.", "std": "단서(그림 등)가 주어진 짧은 이야기를 듣고 내용을 파악할 수 있다.", "codes": "L-3-3-1, L-3-3-2", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 새해 계획, 다짐했다, 공부를 열심히 하겠다, 방학동안 할 일, 가족 행사", "그림을 보며 짧은 이야기(새해 계획 등)를 듣고, 인물과 행동(다짐했다, 공부를 열심히 하겠다. 등)을 알맞게 연결한다.", "그림을 보며 짧은 이야기(방학동안 할 일, 가족 행사 등)를 듣고, 교사의 질문(방학동안 무엇을 할 것인가요? 가족들이 무엇…", "확인(진단형 L-3-3-1·L-3-3-2 섞기)"], "file": "lessons/g34-L-11.html", "st": "soon"}, {"id": "초3~4-듣기-12", "g": "초3~4", "a": "듣기", "lv": 3, "n": 12, "t": "가게 대화와 일기 예보를 들어요", "goal": "일상생활에서의 간단한 대화를 듣고 주요 내용을 파악할 수 있어요.", "std": "일상생활에서의 간단한 대화를 듣고 주요 내용을 파악할 수 있다.", "codes": "L-3-4-1, L-3-4-2", "theme": "생활 대화", "acts": ["낱말·표현 익히기: 마트에서 물건 사기, 지역별 일기 예보, 맑은 날씨, 흐린 날씨, 비오는 날씨", "대화나 이야기(마트에서 물건 사기 등)를 듣고 누가, 어디에서, 무엇을 했는지 보기에서 각각 고른다.", "들은 내용(지역별 일기 예보 등)과 질문에 맞는 그림(맑은 날씨, 흐린 날씨, 비오는 날씨 등)을 고른다.", "확인(진단형 L-3-4-1·L-3-4-2 섞기)"], "file": "lessons/g34-L-12.html", "st": "soon"}, {"id": "초3~4-듣기-13", "g": "초3~4", "a": "듣기", "lv": 4, "n": 13, "t": "수업 이야기를 듣고 내용을 알아요", "goal": "수업과 관련된 주제의 이야기를 듣고 대강의 내용을 파악할 수 있어요.", "std": "수업과 관련된 주제의 이야기를 듣고 대강의 내용을 파악할 수 있다.", "codes": "L-4-1-1, L-4-1-2", "theme": "교과 내용", "acts": ["낱말·표현 익히기: 육지에서 사는 동물, 땅에서 사는 동물, 무엇에 관한 이야기인가요?, 사는 곳, 생김새, 먹이", "수업과 관련된 주제의 이야기나 발표(육지에서 사는 동물, 땅에서 사는 동물 등)를 듣고 교사의 질문(무엇에 관한 이야기인가요…", "수업과 관련한 주제(동물의 한살이 등)을 듣고, 순서(성장과정: 알, 애벌레, 번데기, 나비 등)를 답한다.", "확인(진단형 L-4-1-1·L-4-1-2 섞기)"], "file": "lessons/g34-L-13.html", "st": "soon"}, {"id": "초3~4-듣기-14", "g": "초3~4", "a": "듣기", "lv": 4, "n": 14, "t": "대피 방송을 듣고 행동해요", "goal": "정보를 알리는 말을 듣고 주요 내용과 세부 내용을 찾을 수 있어요.", "std": "정보를 알리는 말을 듣고 주요 내용과 세부 내용을 찾을 수 있다.", "codes": "L-4-2-1, L-4-2-2", "theme": "안전", "acts": ["낱말·표현 익히기: 마을에 대한 설명, 농촌, 산촌, 어촌, 재난 대피 방송, 코와 입을 막기", "정보를 알리는 말(마을에 대한 설명 등)을 듣고, 주요 내용과 세부 내용(농촌, 산촌, 어촌 등)을 찾는다.", "들은 안내(재난 대피 방송 등)에 따라 필요한 정보를 골라 행동으로(코와 입을 막기, 운동장에 나가기 등) 반응한다.", "확인(진단형 L-4-2-1·L-4-2-2 섞기)"], "file": "lessons/g34-L-14.html", "st": "soon"}, {"id": "초3~4-듣기-15", "g": "초3~4", "a": "듣기", "lv": 4, "n": 15, "t": "책과 위인 소개를 들어요", "goal": "이야기나 발표를 듣고 내용을 파악할 수 있어요.", "std": "이야기나 발표를 듣고 내용을 파악할 수 있다.", "codes": "L-4-3-1, L-4-3-2, L-4-3-3", "theme": "발표", "acts": ["낱말·표현 익히기: 책 소개, 위인 소개, 장래 희망, 무엇에 관한 이야기인가요?", "이야기나 발표(책 소개, 위인 소개, 장래 희망 등)를 듣고, 발표자가 소개한 대상을 보기에서 고른다.", "이야기나 발표(책 소개, 위인 소개, 장래 희망 등)를 듣고, 발표 내용과 맞는 그림을 모두 고른다.", "확인(진단형) 이야기나 발표(책 소개, 위인 소개, 장래 희망 등)를 듣고, 들은 내용에 대한 사실 질문(무엇에 관한 이…"], "file": "lessons/g34-L-15.html", "st": "soon"}, {"id": "초3~4-듣기-16", "g": "초3~4", "a": "듣기", "lv": 4, "n": 16, "t": "약속하는 대화를 듣고 목적을 알아요", "goal": "다소 긴 대화를 듣고 상황과 목적을 이해할 수 있어요.", "std": "다소 긴 대화를 듣고 상황과 목적을 이해할 수 있다.", "codes": "L-4-4-1", "theme": "약속", "acts": ["낱말·표현 익히기: 약속을 정하는 대화", "다소 긴 대화나 이야기(약속을 정하는 대화 등)를 듣고 그 상황이나 목적을 대략적으로 답한다.", "같은 방식, 소재를 바꿔 한 번 더", "확인(진단형 L-4-4-1)"], "file": "lessons/g34-L-16.html", "st": "soon"}, {"id": "초3~4-말하기-01", "g": "초3~4", "a": "말하기", "lv": 1, "n": 1, "t": "교실 물건과 동물 이름을 말해요", "goal": "주변의 사물/대상에 대해 짧고 쉬운 단어로 말할 수 있어요.", "std": "주변의 사물/대상에 대해 짧고 쉬운 단어로 말할 수 있다.", "codes": "S-1-1-1, S-1-1-2, S-1-1-3", "theme": "교실 물건", "acts": ["낱말·표현 익히기: 책상, 의자, 칠판, 코끼리, 하마, 기린", "가리키는 교실 사물(책상, 의자, 칠판 등)의 이름을 한 단어로 말한다.", "그림 카드를 보고 동물 이름(코끼리, 하마, 기린 등)을 말한다.", "확인(진단형) 자신이 가진 물건의 이름(연필, 지우개 등)을 말한다."], "file": "lessons/g34-S-01.html", "st": "soon"}, {"id": "초3~4-말하기-02", "g": "초3~4", "a": "말하기", "lv": 1, "n": 2, "t": "친구와 어른에게 인사해요", "goal": "간단한 인사말을 주고받을 수 있어요.", "std": "간단한 인사말을 주고받을 수 있다.", "codes": "S-1-2-1, S-1-2-2", "theme": "인사", "acts": ["낱말·표현 익히기: 안녕, 잘가, 안녕하세요, 안녕히 계세요", "친구와 만나고 헤어질 때 인사말(안녕, 잘가. 등)을 한다.", "어른과 만나고 헤어질 때 인사말(안녕하세요, 안녕히 계세요. 등)을 한다.", "확인(진단형 S-1-2-1·S-1-2-2 섞기)"], "file": "lessons/g34-S-02.html", "st": "soon"}, {"id": "초3~4-말하기-03", "g": "초3~4", "a": "말하기", "lv": 1, "n": 3, "t": "짧게 대답해요", "goal": "간단한 질문에 한두 단어로 대답할 수 있어요.", "std": "간단한 질문에 한두 단어로 대답할 수 있다.", "codes": "S-1-3-1, S-1-3-2, S-1-3-3", "theme": "자기소개", "acts": ["낱말·표현 익히기: 이름이 뭐니?, 저는 00예요, 몇 살이니?, 10, 열 살이에요, 이건 뭐야?", "이름을 묻는 질문(이름이 뭐니? 등)에 자신의 이름(저는 00예요. 등)을 말한다.", "나이를 묻는 질문(몇 살이니? 등)에 숫자나 짧은 문장(10, 열 살이에요. 등)으로 답한다.", "확인(진단형) 물건의 이름을 묻는 질문(이건 뭐야? 등) 에 한 단어(연필이에요. 필통이에요. 등)로 답한다."], "file": "lessons/g34-S-03.html", "st": "soon"}, {"id": "초3~4-말하기-04", "g": "초3~4", "a": "말하기", "lv": 1, "n": 4, "t": "필요한 것을 말해요", "goal": "주요 단어로 의사를 표현할 수 있어요.", "std": "주요 단어로 의사를 표현할 수 있다.", "codes": "S-1-4-1, S-1-4-2, S-1-4-3", "theme": "도움 요청", "acts": ["낱말·표현 익히기: 휴지, 색연필, 놀자, 가자, 축구하자, 싫어요", "활동 중 필요한 것이 있을 때, 그 이름(휴지, 색연필 등)을 말하여 요구한다.", "하고 싶은 활동을 한 단어나 짧은 구(놀자. 가자. 축구하자. 등)로 말한다.", "확인(진단형) 싫거나 어려운 상황에서 거절이나 도움 요청 표현(싫어요. 안돼요. 도와주세요. 등)을 말한다."], "file": "lessons/g34-S-04.html", "st": "soon"}, {"id": "초3~4-말하기-05", "g": "초3~4", "a": "말하기", "lv": 1, "n": 5, "t": "천천히 또박또박 말해요", "goal": "부정확하지만 이해할 수 있는 발음과 속도로 천천히 말할 수 있어요.", "std": "부정확하지만 이해할 수 있는 발음과 속도로 천천히 말할 수 있다.", "codes": "S-1-5-1, S-1-5-2", "theme": "발음", "acts": ["낱말·표현 익히기: 핵심 낱말", "발음이 서툴러도 한음절씩 천천히 말한다.", "상대가 알아듣지 못했을 때 같은 말을 다시 천천히 말한다.", "확인(진단형 S-1-5-1·S-1-5-2 섞기)"], "file": "lessons/g34-S-05.html", "st": "soon"}, {"id": "초3~4-말하기-06", "g": "초3~4", "a": "말하기", "lv": 2, "n": 6, "t": "같이 하자고 말하고 허락을 구해요", "goal": "일상과 학교생활에서 자주 사용하는 문장으로 말할 수 있어요.", "std": "일상과 학교생활에서 자주 사용하는 문장으로 말할 수 있다.", "codes": "S-2-1-1, S-2-1-2, S-2-1-3", "theme": "제안·허락", "acts": ["낱말·표현 익히기: 나랑 같이 축구할래?, 나랑 같이 놀이할래?, 아침에 7시에 일어나요, 8시에 학교에 가요", "제안하는 문장(나랑 같이 축구할래?, 나랑 같이 놀이할래? 등)을 말한다.", "학교 생활에서 허락을 구하는 문장(보건실 가도 돼요? 물 마셔도 돼요? 먹어도 돼요? 등)을 말한다.", "확인(진단형) 나의 하루 일과에 대해 문장(아침에 7시에 일어나요. 8시에 학교에 가요. 등)으로 말한다."], "file": "lessons/g34-S-06.html", "st": "soon"}, {"id": "초3~4-말하기-07", "g": "초3~4", "a": "말하기", "lv": 2, "n": 7, "t": "날짜, 시간, 가격을 말해요", "goal": "일상생활에서 필요한 질문에 간단한 문장으로 대답할 수 있어요.", "std": "일상생활에서 필요한 질문에 간단한 문장으로 대답할 수 있다.", "codes": "S-2-2-1, S-2-2-2, S-2-2-3", "theme": "생활 대화", "acts": ["낱말·표현 익히기: 오늘은 몇일이에요? 지금 몇 시에요?, 오늘은 5월 6일이에요, 지금은 9시 5분이에요, 전화번호가 뭐야?, 내 전화번호는 000-0000-0000야, 이것은 얼마예요?", "날짜와 시간을 묻는 질문(오늘은 몇일이에요? 지금 몇 시에요? 등)에 짧은 문장(오늘은 5월 6일이에요. 지금은 9시 5분이…", "전화번호를 묻는 질문(전화번호가 뭐야? 등)에 간단한 문장(내 전화번호는 000-0000-0000야. 등)으로 답한다.", "확인(진단형) 가격을 묻는 질문(이것은 얼마예요? 등)에 짧게 (이것은 5천원이에요. 등) 답한다."], "file": "lessons/g34-S-07.html", "st": "soon"}, {"id": "초3~4-말하기-08", "g": "초3~4", "a": "말하기", "lv": 2, "n": 8, "t": "학교생활에 필요한 것을 묻고 답해요", "goal": "학교생활에서 필요한 정보를 요구하는 질문과 대답을 할 수 있어요.", "std": "학교생활에서 필요한 정보를 요구하는 질문과 대답을 할 수 있다.", "codes": "S-2-3-1, S-2-3-2, S-2-3-3, S-2-3-4", "theme": "준비물", "acts": ["낱말·표현 익히기: 어떻게 해요?, 가위로 잘라, 풀로 붙여, 색연필 어디 있어요?, 책상 위에 있어, 보건실이 어디에 있어요?", "활동 방법을 모를 때 방법을 묻는 질문(어떻게 해요? 등)을 하거나 해당 질문에 대한 대답(가위로 잘라. 풀로 붙여. 등)을…", "수업 준비물의 위치를 묻는 질문(색연필 어디 있어요? 등)을 하거나 해당 질문에 대한 대답(책상 위에 있어. 등)을 한다.", "확인(진단형) 교실의 위치를 묻는 질문(보건실이 어디에 있어요? 등)을 하거나 해당 질문에 대한 대답(1층에 있어. 등)…"], "file": "lessons/g34-S-08.html", "st": "soon"}, {"id": "초3~4-말하기-09", "g": "초3~4", "a": "말하기", "lv": 2, "n": 9, "t": "하고 싶은 것과 다짐을 말해요", "goal": "간단한 문장으로 의사를 표현할 수 있어요.", "std": "간단한 문장으로 의사를 표현할 수 있다.", "codes": "S-2-4-1, S-2-4-2, S-2-4-3", "theme": "생각 표현", "acts": ["낱말·표현 익히기: 제가 할래요, ~하고 싶어요, 책 읽고 싶어요, 운동장에 가고 싶어요, 학교에 일찍 올게요, 싸우지 않을게요", "하고 싶은 말을 한 문장(제가 할래요. ~하고 싶어요. 책 읽고 싶어요. 운동장에 가고 싶어요. 등)으로 말한다.", "다짐을 한 문장(학교에 일찍 올게요. 싸우지 않을게요. 등)으로 말한다.", "확인(진단형) 도움이 필요한 상황을 한 문장(보건실에 가고 싶어요. 가위가 없어요. 등)으로 말한다."], "file": "lessons/g34-S-09.html", "st": "soon"}, {"id": "초3~4-말하기-10", "g": "초3~4", "a": "말하기", "lv": 2, "n": 10, "t": "띄어서 분명하게 말해요", "goal": "부정확하지만 이해할 수 있는 발음과 속도로 말할 수 있어요.", "std": "부정확하지만 이해할 수 있는 발음과 속도로 말할 수 있다.", "codes": "S-2-5-1, S-2-5-2", "theme": "발음", "acts": ["낱말·표현 익히기: 이것은 내 공책이에요", "짧은 문장(이것은 내 공책이에요. 등)을 말할 때 낱말 사이를 자연스럽게 띄어 말한다.", "상대가 다시 물으면, 같은 말을 조금 더 분명한 발음과 속도로 다시 말한다.", "확인(진단형 S-2-5-1·S-2-5-2 섞기)"], "file": "lessons/g34-S-10.html", "st": "soon"}, {"id": "초3~4-말하기-11", "g": "초3~4", "a": "말하기", "lv": 3, "n": 11, "t": "가족과 친구를 소개해요", "goal": "친숙한 주제에 관해 말할 수 있어요.", "std": "친숙한 주제에 관해 말할 수 있다.", "codes": "S-3-1-1, S-3-1-2", "theme": "가족·소개", "acts": ["낱말·표현 익히기: 가족 소개, 친구 소개, 방과후 활동, 장래희망, 등굣길, 운동장", "친숙한 주제(가족 소개, 친구 소개, 방과후 활동, 장래희망 등)에 관해 소개나 발표를 한다.", "그림이나 사진(등굣길, 운동장)을 보며 관련된 정보를 두 가지 이상 말한다.", "확인(진단형 S-3-1-1·S-3-1-2 섞기)"], "file": "lessons/g34-S-11.html", "st": "soon"}, {"id": "초3~4-말하기-12", "g": "초3~4", "a": "말하기", "lv": 3, "n": 12, "t": "체험학습에서 겪은 일을 말해요", "goal": "겪은 일에 관해 말할 수 있어요.", "std": "겪은 일에 관해 말할 수 있다.", "codes": "S-3-2-1, S-3-2-2, S-3-2-3", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 현장체험학습, 생일 파티, 어제, 오늘", "겪은 일(현장체험학습, 생일 파티 등)을 시간 표현(어제, 오늘 등)을 사용해 말한다.", "겪은 일(현장체험학습, 생일 파티 등)에 나온 사람이나 장소를 포함해 말한다.", "확인(진단형) 겪은 일(현장체험학습, 생일 파티 등)에 대한 느낌을 한 문장으로 말한다."], "file": "lessons/g34-S-12.html", "st": "soon"}, {"id": "초3~4-말하기-13", "g": "초3~4", "a": "말하기", "lv": 3, "n": 13, "t": "수업 시간에 묻고 답해요", "goal": "수업에 참여하여 질문하고 대답할 수 있어요.", "std": "수업에 참여하여 질문하고 대답할 수 있다.", "codes": "S-3-3-1, S-3-3-2", "theme": "수업 참여", "acts": ["낱말·표현 익히기: 무엇으로 관찰해요?, 돋보기로 관찰해요, 어떤 도형이 있나요?, 삼각형, 사각형, 원이 있어요", "수업 중 질문(무엇으로 관찰해요? 등)을 하거나 수업에 대한 대답(돋보기로 관찰해요. 등)을 한다.", "교사의 확인 질문(어떤 도형이 있나요? 등)에 수업 내용과 관련된 말(삼각형, 사각형, 원이 있어요. 등)로 답한다.", "확인(진단형 S-3-3-1·S-3-3-2 섞기)"], "file": "lessons/g34-S-13.html", "st": "soon"}, {"id": "초3~4-말하기-14", "g": "초3~4", "a": "말하기", "lv": 3, "n": 14, "t": "들은 이야기를 전해요", "goal": "전해 들은 짧은 이야기를 전달할 수 있어요.", "std": "전해 들은 짧은 이야기를 전달할 수 있다.", "codes": "S-3-4-1, S-3-4-2", "theme": "말 전달", "acts": ["낱말·표현 익히기: 친구의 생일 파티, 집에 오라고 했어, 축구하자고 했어", "전해 들은 짧은 이야기(친구의 생일 파티 등)에서 시간, 장소, 대상 등을 말한다.", "들은 내용을 전달하는 말(집에 오라고 했어. 축구하자고 했어. 등)로 표현한다.", "확인(진단형 S-3-4-1·S-3-4-2 섞기)"], "file": "lessons/g34-S-14.html", "st": "soon"}, {"id": "초3~4-말하기-15", "g": "초3~4", "a": "말하기", "lv": 3, "n": 15, "t": "알아듣기 쉽게 다시 말해요", "goal": "비교적 정확한 발음으로 말할 수 있어요.", "std": "비교적 정확한 발음으로 말할 수 있다.", "codes": "S-3-5-1, S-3-5-2", "theme": "발음", "acts": ["낱말·표현 익히기: 핵심 낱말", "자신이 하고 싶은 말을 비교적 정확한 발음으로 말한다.", "상대가 다시 묻거나 못 알아들었을 때 같은 내용을 한 번 더 알아 듣기 쉽게 말한다.", "확인(진단형 S-3-5-1·S-3-5-2 섞기)"], "file": "lessons/g34-S-15.html", "st": "soon"}, {"id": "초3~4-말하기-16", "g": "초3~4", "a": "말하기", "lv": 4, "n": 16, "t": "배운 내용을 내 말로 말해요", "goal": "수업 내용과 관련된 주제에 관해 말할 수 있어요.", "std": "수업 내용과 관련된 주제에 관해 말할 수 있다.", "codes": "S-4-1-1, S-4-1-2", "theme": "교과 내용", "acts": ["낱말·표현 익히기: 동물, 식물, 우리 마을, 지도, 방위", "수업 내용(동물, 식물, 우리 마을, 지도, 방위 등)과 관련된 주제에 대해 자신의 말로 표현한다.", "수업에서 배운 내용(동물, 식물, 우리 마을, 지도, 방위 등)을 간략하게 말한다.", "확인(진단형 S-4-1-1·S-4-1-2 섞기)"], "file": "lessons/g34-S-16.html", "st": "soon"}, {"id": "초3~4-말하기-17", "g": "초3~4", "a": "말하기", "lv": 4, "n": 17, "t": "학교 소식을 발표해요", "goal": "정보를 알리는 말을 할 수 있어요.", "std": "정보를 알리는 말을 할 수 있다.", "codes": "S-4-2-1, S-4-2-2", "theme": "학교 행사", "acts": ["낱말·표현 익히기: 옛날과 오늘날의 생활 모습 비교, 교내 학교 행사, 학교의 상징", "학습과 관련한 정보(옛날과 오늘날의 생활 모습 비교 등)를 말한다.", "학교 생활(교내 학교 행사, 학교의 상징 등)에 대한 내용을 발표한다.", "확인(진단형 S-4-2-1·S-4-2-2 섞기)"], "file": "lessons/g34-S-17.html", "st": "soon"}, {"id": "초3~4-말하기-18", "g": "초3~4", "a": "말하기", "lv": 4, "n": 18, "t": "까닭을 들어 내 생각을 말해요", "goal": "수업에 참여하여 자신의 생각을 말할 수 있어요.", "std": "수업에 참여하여 자신의 생각을 말할 수 있다.", "codes": "S-4-3-1, S-4-3-2", "theme": "생각 표현", "acts": ["낱말·표현 익히기: “왜냐하면 ○○이기 때문입니다.”", "이유나 근거를 들어 발표(“왜냐하면 ○○이기 때문입니다.” 등)의 형태로 자신의 생각을 말한다.", "그림이나 이야기 속 인물의 행동에 대해 자신의 생각(\"제 생각에 00이 거짓말을 말한 것은 나쁘다고 생각합니다.\" 등)을 말…", "확인(진단형 S-4-3-1·S-4-3-2 섞기)"], "file": "lessons/g34-S-18.html", "st": "soon"}, {"id": "초3~4-말하기-19", "g": "초3~4", "a": "말하기", "lv": 4, "n": 19, "t": "제안하고 약속하는 대화를 해요", "goal": "상황과 목적에 맞게 대화할 수 있어요.", "std": "상황과 목적에 맞게 대화할 수 있다.", "codes": "S-4-4-1, S-4-4-2", "theme": "약속", "acts": ["낱말·표현 익히기: 제안하기, 약속하기, 발표하는 상황, 짝과 대화하는 상황", "대화(제안하기, 약속하기 등)에서 질문과 대답을 번갈아 하며 관련 발화를 이어 간다.", "상황에 맞는 대화(발표하는 상황, 짝과 대화하는 상황 등)에서 질문과 대답을 번갈아 하며 관련 발화를 이어 간다.", "확인(진단형 S-4-4-1·S-4-4-2 섞기)"], "file": "lessons/g34-S-19.html", "st": "soon"}, {"id": "초3~4-말하기-20", "g": "초3~4", "a": "말하기", "lv": 4, "n": 20, "t": "상대와 상황에 맞게 말해요", "goal": "대화 상대와 맥락을 고려하여 어느 정도 자연스럽게 말할 수 있어요.", "std": "대화 상대와 맥락을 고려하여 어느 정도 자연스럽게 말할 수 있다.", "codes": "S-4-5-1, S-4-5-2, S-4-5-3", "theme": "높임말", "acts": ["낱말·표현 익히기: 발화, 동물 말, 높임 표현 사용하기, 00이 무슨 뜻이야?, 00는 이런 뜻이야, 맞아", "맥락(말(발화/동물 말 등)이 빨라요. 등 동음이의어에 주의하는 대화)을 고려하여 자신이 하고 싶은 말을 한다.", "대화 상대에 따라(높임 표현 사용하기 등) 질문과 대답을 번갈아 하며 관련 발화를 이어 간다.", "확인(진단형) 상대의 말에 맞추어 되묻기(00이 무슨 뜻이야? / 00는 이런 뜻이야. 등), 동의(맞아, 나도 그래. …"], "file": "lessons/g34-S-20.html", "st": "soon"}, {"id": "초3~4-읽기-01", "g": "초3~4", "a": "읽기", "lv": 1, "n": 1, "t": "글자와 낱말을 소리 내어 읽어요", "goal": "글자와 단어를 소리 내어 읽을 수 있어요.", "std": "글자와 단어를 소리 내어 읽을 수 있다.", "codes": "R-1-1-1, R-1-1-2, R-1-1-3", "theme": "한글 자모", "acts": ["낱말·표현 익히기: 가, 나, 모, 수, 사과, 우유", "자음과 모음이 결합된 글자(가, 나, 모, 수 등)를 보고 소리 내어 읽는다.", "그림과 함께 제시된 낱말(사과, 우유, 학교 등)을 보고 소리 내어 읽는다.", "확인(진단형) 교실에서 자주 보는 낱말(학교, 교실 등)을 보고 소리 내어 읽는다."], "file": "lessons/g34-R-01.html", "st": "soon"}, {"id": "초3~4-읽기-02", "g": "초3~4", "a": "읽기", "lv": 1, "n": 2, "t": "낱말을 읽고 그림과 연결해요", "goal": "짧고 쉬운 단어를 읽고 의미를 파악할 수 있어요.", "std": "짧고 쉬운 단어를 읽고 의미를 파악할 수 있다.", "codes": "R-1-2-1, R-1-2-2", "theme": "교실 물건", "acts": ["낱말·표현 익히기: 가방, 우유, 강아지, 책상, 의자, 문", "낱말 카드(가방, 우유, 강아지 등)를 읽고 해당하는 그림이나 실물을 연결한다.", "교실 물건 이름(책상, 의자, 문 등)을 읽고 해당 물건에 사물 이름표를 붙인다.", "확인(진단형 R-1-2-1·R-1-2-2 섞기)"], "file": "lessons/g34-R-02.html", "st": "soon"}, {"id": "초3~4-읽기-03", "g": "초3~4", "a": "읽기", "lv": 1, "n": 3, "t": "학교 안내판을 읽어요", "goal": "생활에서 사용하는 안내/간판 등을 파악할 수 있어요.", "std": "생활에서 사용하는 안내/간판 등을 파악할 수 있다.", "codes": "R-1-3-1, R-1-3-2, R-1-3-3", "theme": "학교 장소", "acts": ["낱말·표현 익히기: 약국, 병원, 보건실, 화장실, 줄 서기, 손 씻기", "표지판, 간판에 쓰여진 어휘(약국, 병원, 보건실, 화장실 등)를 읽고 해당 장소를 가리키거나 이동한다.", "생활 규칙 안내(줄 서기, 손 씻기 등)를 읽고 해야 할 행동을 짧은 말이나 몸짓으로 나타낸다.", "확인(진단형) 신발장, 책상, 사물함 등에 붙은 이름표를 읽고 자신의 자리를 찾는다."], "file": "lessons/g34-R-03.html", "st": "soon"}, {"id": "초3~4-읽기-04", "g": "초3~4", "a": "읽기", "lv": 1, "n": 4, "t": "받침을 살펴 바르게 읽어요", "goal": "한글 자음과 모음, 받침 등 글자를 식별하여 짧은 문장을 읽을 수 있어요.", "std": "한글 자음과 모음, 받침 등 글자를 식별하여 짧은 문장을 읽을 수 있다.", "codes": "R-1-4-1, R-1-4-2, R-1-4-3", "theme": "한글 자모", "acts": ["낱말·표현 익히기: 오리, 우리 중 고르기, 사과, 자과 중 고르기, 물병, 문병 중 고르기", "그림(오리 등)을 보고 알맞은 모음(오리, 우리 중 고르기)이 들어간 글자를 골라 읽는다.", "그림(사과 등)을 보고 알맞은 자음(사과, 자과 중 고르기)이 들어간 글자를 골라 읽는다.", "확인(진단형) 그림(물병 등)을 보고 알맞은 받침(물병, 문병 중 고르기)이 들어간 글자를 골라 읽는다."], "file": "lessons/g34-R-04.html", "st": "soon"}, {"id": "초3~4-읽기-05", "g": "초3~4", "a": "읽기", "lv": 2, "n": 5, "t": "띄어서 문장을 읽어요", "goal": "문장을 알맞게 띄어 읽을 수 있어요.", "std": "문장을 알맞게 띄어 읽을 수 있다.", "codes": "R-2-1-1", "theme": "문장", "acts": ["낱말·표현 익히기: 우유를 마셔요, 운동장에서 놀아요, 집에서 숙제를 해요", "두세 어절로 된 짧은 문장(우유를 마셔요. 운동장에서 놀아요. 집에서 숙제를 해요. 등)을 낱말 사이에서 띄어 읽는다.", "같은 방식, 소재를 바꿔 한 번 더", "확인(진단형 R-2-1-1)"], "file": "lessons/g34-R-05.html", "st": "soon"}, {"id": "초3~4-읽기-06", "g": "초3~4", "a": "읽기", "lv": 2, "n": 6, "t": "문장을 읽고 알맞게 행동해요", "goal": "문장의 의미를 대강 파악할 수 있어요.", "std": "문장의 의미를 대강 파악할 수 있다.", "codes": "R-2-2-1, R-2-2-2", "theme": "교실 지시", "acts": ["낱말·표현 익히기: 알림장을 쓰세요, 낙서하지 마세요, 도서관에서 책을 빌려요, 급식실에서 밥을 먹어요", "짧은 지시문(알림장을 쓰세요. 낙서하지 마세요. 등)을 읽고 문장에 맞는 행동을 한다.", "문장(도서관에서 책을 빌려요. 급식실에서 밥을 먹어요. 등)을 읽고 문장의 내용에 알맞은 그림에 표시한다.", "확인(진단형 R-2-2-1·R-2-2-2 섞기)"], "file": "lessons/g34-R-06.html", "st": "soon"}, {"id": "초3~4-읽기-07", "g": "초3~4", "a": "읽기", "lv": 2, "n": 7, "t": "알림장과 안내문에서 정보를 찾아요", "goal": "알림장, 초대장 등의 글을 읽고 정보를 찾을 수 있어요.", "std": "알림장, 초대장 등의 글을 읽고 정보를 찾을 수 있다.", "codes": "R-2-3-1, R-2-3-2", "theme": "준비물", "acts": ["낱말·표현 익히기: 준비물: 리코더와 실내화 가져오기, 리코더, 실내화, 어린이날 행사를 합니다, 장소, 일시", "알림장(준비물: 리코더와 실내화 가져오기 등)을 읽고 필요한 준비물(리코더, 실내화 등)을 고른다.", "게시판 안내문(어린이날 행사를 합니다. 등)에서 필요한 정보(장소, 일시, 대상 등)에 동그라미를 한다.", "확인(진단형 R-2-3-1·R-2-3-2 섞기)"], "file": "lessons/g34-R-07.html", "st": "soon"}, {"id": "초3~4-읽기-08", "g": "초3~4", "a": "읽기", "lv": 2, "n": 8, "t": "긴 문장을 끊어 읽어요", "goal": "다양한 구조의 문장을 의미 단위로 끊어 읽을 수 있어요.", "std": "다양한 구조의 문장을 의미 단위로 끊어 읽을 수 있다.", "codes": "R-2-4-1, R-2-4-2", "theme": "문장", "acts": ["낱말·표현 익히기: 원인과 결과, 비교와 대조의 문장, 호응 관계에 따른 문장, 기린은 목이 길어요, 토끼는 앞발이 짧다, 우리학교는 운동장이 넓어요", "다양한 구조의 문장(원인과 결과, 비교와 대조의 문장, 호응 관계에 따른 문장 등)을 의미 단위로 나누어 읽는다.", "안은문장(기린은 목이 길어요. 토끼는 앞발이 짧다. 우리학교는 운동장이 넓어요. 등)을 의미 단위로 나누어 읽는다.", "확인(진단형 R-2-4-1·R-2-4-2 섞기)"], "file": "lessons/g34-R-08.html", "st": "soon"}, {"id": "초3~4-읽기-09", "g": "초3~4", "a": "읽기", "lv": 3, "n": 9, "t": "나라 소개 글을 읽어요", "goal": "친숙한 주제에 관한 글을 읽고 대강의 내용을 파악할 수 있어요.", "std": "친숙한 주제에 관한 글을 읽고 대강의 내용을 파악할 수 있다.", "codes": "R-3-1-1, R-3-1-2", "theme": "가족·소개", "acts": ["낱말·표현 익히기: 나라 소개, 방과후 활동, 장래희망", "친숙한 주제(나라 소개, 방과후 활동, 장래희망 등)의 글을 읽고, 내용에 맞는 그림을 고른다.", "친숙한 주제(나라 소개, 방과후 활동, 장래희망 등)의 글을 읽고, 주요 정보를 찾아 답한다.", "확인(진단형 R-3-1-1·R-3-1-2 섞기)"], "file": "lessons/g34-R-09.html", "st": "soon"}, {"id": "초3~4-읽기-10", "g": "초3~4", "a": "읽기", "lv": 3, "n": 10, "t": "중심 내용과 세부 내용을 찾아요", "goal": "글을 읽고 중심 내용과 세부 내용을 찾을 수 있어요.", "std": "글을 읽고 중심 내용과 세부 내용을 찾을 수 있다.", "codes": "R-3-2-1, R-3-2-2, R-3-2-3", "theme": "중심 내용", "acts": ["낱말·표현 익히기: 생활문, 의견을 나타내는 글", "글(생활문, 의견을 나타내는 글 등)을 읽고 알맞은 제목이나 주제를 찾는다.", "글(생활문, 의견을 나타내는 글 등)에서 중요한 낱말이나 문장에 밑줄을 친다.", "확인(진단형) 글(생활문, 의견을 나타내는 글 등)에서 중심 내용과 세부 내용을 구분한다."], "file": "lessons/g34-R-10.html", "st": "soon"}, {"id": "초3~4-읽기-11", "g": "초3~4", "a": "읽기", "lv": 3, "n": 11, "t": "가정통신문과 기사를 읽어요", "goal": "이야기나 설명하는 글을 읽고 주요 내용을 파악할 수 있어요.", "std": "이야기나 설명하는 글을 읽고 주요 내용을 파악할 수 있다.", "codes": "R-3-3-1, R-3-3-2", "theme": "학교 행사", "acts": ["낱말·표현 익히기: 기사, 안내 방송문, 가정통신문", "글(기사, 안내 방송문, 가정통신문 등)을 읽고 가장 알맞은 제목이나 중심 문장을 보기에서 고른다.", "글(기사, 안내 방송문, 가정통신문 등)에서 중요한 낱말이나 문장에 밑줄 친다.", "확인(진단형 R-3-3-1·R-3-3-2 섞기)"], "file": "lessons/g34-R-11.html", "st": "soon"}, {"id": "초3~4-읽기-12", "g": "초3~4", "a": "읽기", "lv": 3, "n": 12, "t": "편지와 옛이야기의 중심 문장을 찾아요", "goal": "짧은 글을 읽고 중심 내용을 찾을 수 있어요.", "std": "짧은 글을 읽고 중심 내용을 찾을 수 있다.", "codes": "R-3-4-1, R-3-4-2", "theme": "이야기", "acts": ["낱말·표현 익히기: 편지글, 초대장, 전래 동화, 이솝 우화", "짧은 글(편지글, 초대장, 전래 동화, 이솝 우화 등)을 읽고 가장 알맞은 제목이나 중심 문장을 보기에서 고른다.", "짧은 글(편지글, 초대장, 전래 동화, 이솝 우화 등)에서 중요한 낱말이나 문장 1개 이상에 밑줄 친다.", "확인(진단형 R-3-4-1·R-3-4-2 섞기)"], "file": "lessons/g34-R-12.html", "st": "soon"}, {"id": "초3~4-읽기-13", "g": "초3~4", "a": "읽기", "lv": 4, "n": 13, "t": "기행문과 위인전을 읽어요", "goal": "다양한 주제의 글을 읽고 전반적인 내용을 파악할 수 있어요.", "std": "다양한 주제의 글을 읽고 전반적인 내용을 파악할 수 있다.", "codes": "R-4-1-1, R-4-1-2, R-4-1-3", "theme": "교과 내용", "acts": ["낱말·표현 익히기: 기행문, 위인전", "다양한 주제의 글(기행문, 위인전 등)을 읽고 누가, 어디에서, 무엇을 했는지 각각 표시한다.", "다양한 주제의 글(기행문, 위인전 등)을 읽고 일의 순서대로 그림 카드로 나타낸다.", "확인(진단형) 다양한 주제의 글(기행문, 위인전 등)을 읽고 내용과 맞는 문장에 동그라미를 한다."], "file": "lessons/g34-R-13.html", "st": "soon"}, {"id": "초3~4-읽기-14", "g": "초3~4", "a": "읽기", "lv": 4, "n": 14, "t": "사실과 생각을 구분해요", "goal": "이야기를 읽고 사실과 생각이나 느낌을 구분할 수 있어요.", "std": "이야기를 읽고 사실과 생각이나 느낌을 구분할 수 있다.", "codes": "R-4-2-1, R-4-2-2, R-4-2-3", "theme": "이야기", "acts": ["낱말·표현 익히기: 전래 동화, 이솝 우화, 설레다, 기대되다, 즐겁다, 부끄럽다", "이야기(전래 동화, 이솝 우화 등)를 읽고 문장 카드를 일이 일어난 순서대로 놓는다.", "이야기(전래 동화, 이솝 우화 등)를 읽고 등장인물에게 생긴 일이 나타난 문장을 찾는다.", "확인(진단형) 이야기(전래 동화, 이솝 우화 등)을 읽고 인물의 생각이나 느낌을 나타내는 말(설레다. 기대되다. 즐겁다.…"], "file": "lessons/g34-R-14.html", "st": "soon"}, {"id": "초3~4-읽기-15", "g": "초3~4", "a": "읽기", "lv": 4, "n": 15, "t": "교과서 글을 읽고 이해해요", "goal": "교과서에 나오는 글을 읽고 주요 내용을 파악할 수 있어요.", "std": "교과서에 나오는 글을 읽고 주요 내용을 파악할 수 있다.", "codes": "R-4-3-1, R-4-3-2, R-4-3-3", "theme": "교과서", "acts": ["낱말·표현 익히기: 핵심 낱말", "교과서 글을 읽고 가장 알맞은 제목이나 중심 문장을 보기에서 고른다.", "교과서의 글을 읽고, 글에서 설명하는 대상을 고른다.", "확인(진단형) 교과서 글을 읽고 내용을 묻는 질문에 글 속 낱말을 사용해 답한다."], "file": "lessons/g34-R-15.html", "st": "soon"}, {"id": "초3~4-읽기-16", "g": "초3~4", "a": "읽기", "lv": 4, "n": 16, "t": "글의 흐름을 따라 읽어요", "goal": "다양한 유형의 글을 읽고 내용의 흐름을 이해할 수 있어요.", "std": "다양한 유형의 글을 읽고 내용의 흐름을 이해할 수 있다.", "codes": "R-4-4-1, R-4-4-2", "theme": "중심 내용", "acts": ["낱말·표현 익히기: 이야기글, 설명하는 글, 주장하는 글, 만화, 인터넷 게시글", "글(이야기글, 설명하는 글, 주장하는 글, 만화, 인터넷 게시글 등)을 읽고 사건 그림이나 문장을 순서대로 배열한다.", "글(이야기글, 설명하는 글, 주장하는 글, 만화, 인터넷 게시글 등)을 읽고 줄거리와 맞지 않는 문장을 보기에서 골라 지운다.", "확인(진단형 R-4-4-1·R-4-4-2 섞기)"], "file": "lessons/g34-R-16.html", "st": "soon"}, {"id": "초3~4-쓰기-01", "g": "초3~4", "a": "쓰기", "lv": 1, "n": 1, "t": "글자와 낱말을 따라 써요", "goal": "글자와 단어를 쓸 수 있어요.", "std": "글자와 단어를 쓸 수 있다.", "codes": "W-1-1-1, W-1-1-2, W-1-1-3", "theme": "한글 자모", "acts": ["낱말·표현 익히기: 가, 나, 다, 사과, 우유, 책", "제시한 글자(가, 나, 다 등)를 보고 같은 글자를 따라 쓴다.", "그림 옆에 제시된 낱말(사과, 우유, 책 등)을 보고 따라 쓴다.", "확인(진단형) 자기 이름이나 교실에서 자주 쓰는 낱말(학교, 교실 등)을 보고 쓴다."], "file": "lessons/g34-W-01.html", "st": "soon"}, {"id": "초3~4-쓰기-02", "g": "초3~4", "a": "쓰기", "lv": 1, "n": 2, "t": "획순에 맞게 글자를 써요", "goal": "필순과 자형에 맞게 글자를 쓸 수 있어요.", "std": "필순과 자형에 맞게 글자를 쓸 수 있다.", "codes": "W-1-2-1, W-1-2-2", "theme": "한글 자모", "acts": ["낱말·표현 익히기: 라, 모, 부, 차, 커, 트", "글자(라, 모, 부, 차, 커, 트, 해 등)의 획을 차례대로 따라 쓴다.", "글자(사, 우, 교 등)를 자형에 맞게 쓴다.", "확인(진단형 W-1-2-1·W-1-2-2 섞기)"], "file": "lessons/g34-W-02.html", "st": "soon"}, {"id": "초3~4-쓰기-03", "g": "초3~4", "a": "쓰기", "lv": 1, "n": 3, "t": "내 이름과 나이를 써요", "goal": "인사말이나 간단한 신상 정보(이름, 나이 등)를 쓸 수 있어요.", "std": "인사말이나 간단한 신상 정보(이름, 나이 등)를 쓸 수 있다.", "codes": "W-1-3-1, W-1-3-2, W-1-3-3", "theme": "자기소개", "acts": ["낱말·표현 익히기: 10, 열 살, 3, 3학년", "자기 이름을 쓴다.", "나이(10, 열 살 등)나 학년(3, 3학년 등)을 숫자와 낱말로 쓴다.", "확인(진단형) 간단한 인사말을 보고 따라 쓴다."], "file": "lessons/g34-W-03.html", "st": "soon"}, {"id": "초3~4-쓰기-04", "g": "초3~4", "a": "쓰기", "lv": 1, "n": 4, "t": "그림을 보고 낱말을 써요", "goal": "시각 자료를 보고 해당하는 단어를 쓸 수 있어요.", "std": "시각 자료를 보고 해당하는 단어를 쓸 수 있다.", "codes": "W-1-4-1", "theme": "교실 물건", "acts": ["낱말·표현 익히기: 시계, 자동차, 칠판, 사물과 일치하는 쓰기", "시각 자료(시계, 자동차, 칠판 등)을 보고 알맞은 낱말을 쓴다.", "같은 방식, 소재를 바꿔 한 번 더", "확인(진단형 W-1-4-1)"], "file": "lessons/g34-W-04.html", "st": "soon"}, {"id": "초3~4-쓰기-05", "g": "초3~4", "a": "쓰기", "lv": 2, "n": 5, "t": "그림을 보고 문장을 써요", "goal": "단어와 문장을 쓸 수 있어요.", "std": "단어와 문장을 쓸 수 있다.", "codes": "W-2-1-1, W-2-1-2, W-2-1-3", "theme": "문장", "acts": ["낱말·표현 익히기: 창문을 여는 모습, 창문, 창문을 열어요, 방에 피아노가 있어요, 교실에 책상이 있어요, 책을 읽어요", "그림(창문을 여는 모습 등)에 맞는 낱말(창문 등)을 넣어 짧은 문장(창문을 열어요. 등)을 완성한다.", "여러 가지 물건 사진이나 그림을 보고 (방에 피아노가 있어요. 교실에 책상이 있어요. 등) 문장을 완성한다.", "확인(진단형) 인물이 하는 일을 짧은 문장(책을 읽어요. 편지를 써요. 등)으로 쓴다."], "file": "lessons/g34-W-05.html", "st": "soon"}, {"id": "초3~4-쓰기-06", "g": "초3~4", "a": "쓰기", "lv": 2, "n": 6, "t": "어구와 문장을 받아써요", "goal": "소리와 표기의 차이를 알고 어구와 문장 단위의 받아쓰기를 할 수 있어요.", "std": "소리와 표기의 차이를 알고 어구와 문장 단위의 받아쓰기를 할 수 있다.", "codes": "W-2-2-1, W-2-2-2", "theme": "받아쓰기", "acts": ["낱말·표현 익히기: 사회, 수학, 한국어, 음악, \"부엌\"에서 요리를 해요, \"숲\"으로 가요", "천천히 읽어 주는 익숙한 낱말(사회, 수학, 한국어, 음악 등)을 듣고 실제 표기에 맞는 글자로 받아쓴다.", "그림을 보고 받침이 있는 어구와 문장(\"부엌\"에서 요리를 해요. \"숲\"으로 가요. 등)을 듣고 표기에 맞는 글자로 구별하여 …", "확인(진단형 W-2-2-1·W-2-2-2 섞기)"], "file": "lessons/g34-W-06.html", "st": "soon"}, {"id": "초3~4-쓰기-07", "g": "초3~4", "a": "쓰기", "lv": 2, "n": 7, "t": "겪은 일을 여러 문장으로 써요", "goal": "겪은 일을 여러 개의 문장으로 쓸 수 있어요.", "std": "겪은 일을 여러 개의 문장으로 쓸 수 있다.", "codes": "W-2-3-1", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 놀이동산 사진, 수영장 사진, 놀이 동산에 갔어요, 놀이 기구를 탔어요, 재밌었어요", "사진 또는 그림(놀이동산 사진, 수영장 사진 등)을 보고 겪은 일에 관해 여러 개의 문장(놀이 동산에 갔어요. 놀이 기구를 …", "같은 방식, 소재를 바꿔 한 번 더", "확인(진단형 W-2-3-1)"], "file": "lessons/g34-W-07.html", "st": "soon"}, {"id": "초3~4-쓰기-08", "g": "초3~4", "a": "쓰기", "lv": 2, "n": 8, "t": "준비물과 할 일을 메모해요", "goal": "생활에 필요한 간단한 메모를 할 수 있어요.", "std": "생활에 필요한 간단한 메모를 할 수 있다.", "codes": "W-2-4-1, W-2-4-2", "theme": "준비물", "acts": ["낱말·표현 익히기: 그림, 사진, 스티커, 줄넘기, 운동화, 모자", "시각 자료(그림, 사진, 스티커 등)를 보고 필요한 준비물(줄넘기, 운동화, 모자, 물 등)을 쓴다.", "시각 자료(그림, 사진, 스티커 등)를 보고 숙제나 해야 할 일을 한 문장(숙제를 해요. 피아노를 쳐요. 물건을 사요. 등)…", "확인(진단형 W-2-4-1·W-2-4-2 섞기)"], "file": "lessons/g34-W-08.html", "st": "soon"}, {"id": "초3~4-쓰기-09", "g": "초3~4", "a": "쓰기", "lv": 3, "n": 9, "t": "까닭과 장소를 넣어 문장을 써요", "goal": "다양한 구조의 문장을 쓸 수 있어요.", "std": "다양한 구조의 문장을 쓸 수 있다.", "codes": "W-3-1-1, W-3-1-2, W-3-1-3, W-3-1-4", "theme": "문장", "acts": ["낱말·표현 익히기: 강아지가 귀여워요, 놀이터에서 놀아요, 김밥은 맛있어서 좋아요, 졸려서 자요, 빵을 먹고 책을 읽어요", "대상과 특징을 넣어 한 문장(강아지가 귀여워요. 등)으로 쓴다.", "장소를 나타내는 말을 넣어 한 문장(놀이터에서 놀아요. 등)으로 쓴다.", "확인(진단형) 알맞은 까닭을 넣어 한 문장(김밥은 맛있어서 좋아요. 졸려서 자요. 등)으로 쓴다."], "file": "lessons/g34-W-09.html", "st": "soon"}, {"id": "초3~4-쓰기-10", "g": "초3~4", "a": "쓰기", "lv": 3, "n": 10, "t": "시제에 맞게 문장을 써요", "goal": "어느 정도 어법에 맞게 단어나 문장을 쓸 수 있어요.", "std": "어느 정도 어법에 맞게 단어나 문장을 쓸 수 있다.", "codes": "W-3-2-1, W-3-2-2, W-3-2-3", "theme": "문장", "acts": ["낱말·표현 익히기: 친구가, 어머니께서, 책을 읽어요, 책을 읽으세요, 학교에 가요, 교실에서 공부해요", "그림을 보고 주어(친구가, 어머니께서 등)와 서술어(책을 읽어요. 책을 읽으세요. 등)가 어울리는 문장을 쓴다.", "주어진 두 가지 이상의 낱말을 자연스럽게 이어 문장을 만든다. (학교에 가요, 교실에서 공부해요. 등)", "확인(진단형) 시제에 맞는 문장(어제 ~했어요, 지금 ~하고 있어요, 내일 ~할 거예요. 등)을 완성한다."], "file": "lessons/g34-W-10.html", "st": "soon"}, {"id": "초3~4-쓰기-11", "g": "초3~4", "a": "쓰기", "lv": 3, "n": 11, "t": "편지를 써요", "goal": "소개하거나 마음을 전하는 글을 쓸 수 있어요.", "std": "소개하거나 마음을 전하는 글을 쓸 수 있다.", "codes": "W-3-3-1, W-3-3-2", "theme": "마음 전하기", "acts": ["낱말·표현 익히기: 가족, 학용품", "소개하거나 설명할 대상(가족, 학용품 등)의 이름과 특징을 쓴다.", "읽는 사람에게 전하고 싶은 말, 글을 쓰는 까닭이 드러나게 편지를 쓴다.", "확인(진단형 W-3-3-1·W-3-3-2 섞기)"], "file": "lessons/g34-W-11.html", "st": "soon"}, {"id": "초3~4-쓰기-12", "g": "초3~4", "a": "쓰기", "lv": 3, "n": 12, "t": "문자와 게시글로 알려요", "goal": "일상과 학교생활에서 필요한 정보를 전달하는 글을 간략하게 쓸 수 있어요.", "std": "일상과 학교생활에서 필요한 정보를 전달하는 글을 간략하게 쓸 수 있다.", "codes": "W-3-4-1, W-3-4-2", "theme": "학교 행사", "acts": ["낱말·표현 익히기: 광고, 인터넷 게시글, 문자 메세지, 교내 학교 행사, 학교의 상징", "일상 생활에서 필요한 정보를 전달하는 글(광고, 인터넷 게시글, 문자 메세지 등)을 간략하게 쓴다.", "학교 생활에서 필요한 정보를 전달하는 글(교내 학교 행사, 학교의 상징 등)을 간략하게 쓴다.", "확인(진단형 W-3-4-1·W-3-4-2 섞기)"], "file": "lessons/g34-W-12.html", "st": "soon"}, {"id": "초3~4-쓰기-13", "g": "초3~4", "a": "쓰기", "lv": 4, "n": 13, "t": "근거를 들어 생각을 써요", "goal": "주제가 드러나게 글을 쓸 수 있어요.", "std": "주제가 드러나게 글을 쓸 수 있다.", "codes": "W-4-1-1", "theme": "생각 표현", "acts": ["낱말·표현 익히기: 학급 회의 안건, 학급 규칙, 체험학습 보고서", "정한 주제(학급 회의 안건, 학급 규칙, 체험학습 보고서 등)에 대해 생각이나 주장을 뒷받침하는 이유를 들어 글을 쓴다.", "같은 방식, 소재를 바꿔 한 번 더", "확인(진단형 W-4-1-1)"], "file": "lessons/g34-W-13.html", "st": "soon"}, {"id": "초3~4-쓰기-14", "g": "초3~4", "a": "쓰기", "lv": 4, "n": 14, "t": "문장을 바르게 고쳐 써요", "goal": "비교적 어법에 맞게 단어나 문장을 쓸 수 있어요.", "std": "비교적 어법에 맞게 단어나 문장을 쓸 수 있다.", "codes": "W-4-2-1, W-4-2-2", "theme": "문장", "acts": ["낱말·표현 익히기: 은, 는, 이, 가, 과거, 현재", "주어와 서술어가 어울리도록 문장을 쓴다.", "조사(은/는/이/가 등), 어미(-자,-고,-다 등) 시제(과거, 현재, 미래)를 고쳐 문장을 다시 쓴다.", "확인(진단형 W-4-2-1·W-4-2-2 섞기)"], "file": "lessons/g34-W-14.html", "st": "soon"}, {"id": "초3~4-쓰기-15", "g": "초3~4", "a": "쓰기", "lv": 4, "n": 15, "t": "시간 순서대로 일기를 써요", "goal": "자신의 경험과 감정이 잘 드러나게 일기를 쓸 수 있어요.", "std": "자신의 경험과 감정이 잘 드러나게 일기를 쓸 수 있다.", "codes": "W-4-3-1, W-4-3-2", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 핵심 낱말", "자신이 겪은 일을 시간, 장소, 행동이 드러나게 쓰고 그에 대한 느낌이나 생각을 쓴다.", "경험한 일을 시간에 따라 순서대로 쓰고 경험을 통해 느낀점을 쓴다.", "확인(진단형 W-4-3-1·W-4-3-2 섞기)"], "file": "lessons/g34-W-15.html", "st": "soon"}, {"id": "초3~4-쓰기-16", "g": "초3~4", "a": "쓰기", "lv": 4, "n": 16, "t": "학교 행사를 알리는 글을 써요", "goal": "일상과 학교생활에서 필요한 정보를 전달하는 글을 쓸 수 있어요.", "std": "일상과 학교생활에서 필요한 정보를 전달하는 글을 쓸 수 있다.", "codes": "W-4-4-1, W-4-4-2", "theme": "학교 행사", "acts": ["낱말·표현 익히기: 광고, 인터넷 게시글, 문자 메세지, 교내 학교 행사, 학교의 상징", "일상 생활에서 필요한 정보를 전달하는 글(광고, 인터넷 게시글, 문자 메세지 등)을 쓴다.", "학교 생활에서 필요한 정보를 전달하는 글(교내 학교 행사, 학교의 상징 등)을 쓴다.", "확인(진단형 W-4-4-1·W-4-4-2 섞기)"], "file": "lessons/g34-W-16.html", "st": "soon"}, {"id": "초5~6-듣기-01", "g": "초5~6", "a": "듣기", "lv": 1, "n": 1, "t": "낱말을 듣고 찾아요", "goal": "짧고 쉬운 단어를 듣고 대상을 찾을 수 있어요.", "std": "짧고 쉬운 단어를 듣고 대상을 찾을 수 있다.", "codes": "L-1-1-1, L-1-1-2, L-1-1-3, L-1-1-4, L-1-1-5", "theme": "교실 물건", "acts": ["낱말·표현 익히기: 연필, 지우개, 공책, 사과, 포도, 우유", "교실 사물(연필, 지우개, 공책 등의 학용품 등)을 말하면, 해당 사물을 가리킨다.", "음식 이름(사과, 포도, 우유 등)을 말하면, 해당 사물을 가리킨다.", "확인(진단형) 생활 용품(모자, 가방, 책상, 의자 등)을 말하면, 해당 사물을 가리킨다."], "file": "lessons/g56-L-01.html", "st": "soon"}, {"id": "초5~6-듣기-02", "g": "초5~6", "a": "듣기", "lv": 1, "n": 2, "t": "만나고 헤어질 때 인사해요", "goal": "간단한 인사말을 듣고 이해할 수 있어요.", "std": "간단한 인사말을 듣고 이해할 수 있다.", "codes": "L-1-2-1, L-1-2-2", "theme": "인사", "acts": ["낱말·표현 익히기: 안녕하세요, 안녕히 계세요, 안녕히 가세요, 내일 봐요", "만나고 헤어질 때 인사말(안녕하세요, 안녕히 계세요 등)에 답한다.", "만나고 헤어질 때 인사말(안녕히 가세요, 내일 봐요. 등)에 알맞은 표정이나 몸짓으로 반응한다.", "확인(진단형 L-1-2-1·L-1-2-2 섞기)"], "file": "lessons/g56-L-02.html", "st": "soon"}, {"id": "초5~6-듣기-03", "g": "초5~6", "a": "듣기", "lv": 1, "n": 3, "t": "학교 규칙을 듣고 지켜요", "goal": "학교에서 사용하는 지시를 듣고 따를 수 있어요.", "std": "학교에서 사용하는 지시를 듣고 따를 수 있다.", "codes": "L-1-3-1, L-1-3-2", "theme": "교실 지시", "acts": ["낱말·표현 익히기: 실내화를 신으세요, 복도에서 뛰지 마세요, 실험도구를 만지지 마세요, 사용 후 제자리에 놓으세요", "학교에서 사용하는 지시(실내화를 신으세요. 복도에서 뛰지 마세요. 등)를 듣고, 적절한 행동을 한다.", "수업 시간 내 사용하는 지시(실험도구를 만지지 마세요. 사용 후 제자리에 놓으세요. 등)를 듣고, 적절한 행동을 한다.", "확인(진단형 L-1-3-1·L-1-3-2 섞기)"], "file": "lessons/g56-L-03.html", "st": "soon"}, {"id": "초5~6-듣기-04", "g": "초5~6", "a": "듣기", "lv": 1, "n": 4, "t": "비슷한 소리를 구별해요", "goal": "소리를 듣고 단어를 식별할 수 있어요.", "std": "소리를 듣고 단어를 식별할 수 있다.", "codes": "L-1-4-1, L-1-4-2", "theme": "발음", "acts": ["낱말·표현 익히기: 오리, 우리, 이리 중에서 찾기, 발-팔, 볼-벌, 달-딸", "단어(오리 등)를 듣고 소리와 일치하는 낱말 카드(오리, 우리, 이리 중에서 찾기)를 찾는다.", "비슷한 소리가 나는 두 단어(발-팔, 볼-벌, 달-딸 등)를 듣고 구별하여 가리킨다.", "확인(진단형 L-1-4-1·L-1-4-2 섞기)"], "file": "lessons/g56-L-04.html", "st": "soon"}, {"id": "초5~6-듣기-05", "g": "초5~6", "a": "듣기", "lv": 2, "n": 5, "t": "길을 묻고 답하는 대화를 들어요", "goal": "일상과 학교생활에서 자주 사용하는 기초적인 대화 내용을 듣고 파악할 수 있어요.", "std": "일상과 학교생활에서 자주 사용하는 기초적인 대화 내용을 듣고 파악할 수 있다.", "codes": "L-2-1-1, L-2-1-2, L-2-1-3", "theme": "생활 대화", "acts": ["낱말·표현 익히기: 병원이 어디에 있어요?, 병원은 육교를 건너서 가요, 경찰서는 어디에 있어요?, 경찰서는 마트 오른쪽에 있어요, 어디에 가요? 병원은 어디에 있어요?, 이건 얼마예요?", "도움을 요청하는 대화(병원이 어디에 있어요? / 병원은 육교를 건너서 가요., 경찰서는 어디에 있어요? / 경찰서는 마트 오…", "정보를 묻는 대화(이건 얼마예요?, 지금 몇 시예요? 등)를 듣고, 안내된 정보를 고른다.", "확인(진단형) 감정을 나타내는 대화(오늘 기분이 어때요? / 기분이 좋아요. 싫어요. 떨려요. 즐거워요. 화가 나요. 등…"], "file": "lessons/g56-L-05.html", "st": "soon"}, {"id": "초5~6-듣기-06", "g": "초5~6", "a": "듣기", "lv": 2, "n": 6, "t": "수업 안내를 듣고 행동해요", "goal": "수업에서 자주 쓰는 문장을 듣고 의미를 파악할 수 있어요.", "std": "수업에서 자주 쓰는 문장을 듣고 의미를 파악할 수 있다.", "codes": "L-2-2-1", "theme": "교실 지시", "acts": ["낱말·표현 익히기: ~~를 조사하세요, 알맞은 그림을 찾아보세요, 모둠을 만드세요", "교사의 수업 안내 문장(~~를 조사하세요. 알맞은 그림을 찾아보세요. 모둠을 만드세요. 등)을 듣고, 해당 행동을 수행한다.", "같은 방식, 소재를 바꿔 한 번 더", "확인(진단형 L-2-2-1)"], "file": "lessons/g56-L-06.html", "st": "soon"}, {"id": "초5~6-듣기-07", "g": "초5~6", "a": "듣기", "lv": 2, "n": 7, "t": "위치와 색깔을 듣고 찾아요", "goal": "주변의 사물과 대상에 관한 간단한 말을 듣고 파악할 수 있어요.", "std": "주변의 사물과 대상에 관한 간단한 말을 듣고 파악할 수 있다.", "codes": "L-2-3-1, L-2-3-2", "theme": "위치·모양", "acts": ["낱말·표현 익히기: 필통 안에 자가 있어요, 사물함 안에 휴지가 있어요, 작은 자전거, 녹색 신호, 하얀 구름", "주변 사물의 위치(필통 안에 자가 있어요. 사물함 안에 휴지가 있어요. 등)를 듣고, 알맞은 그림을 손가락으로 가리킨다.", "주변 대상의 색깔이나 크기(작은 자전거, 녹색 신호등, 하얀 구름 등)를 듣고, 맞는 그림을 고른다.", "확인(진단형 L-2-3-1·L-2-3-2 섞기)"], "file": "lessons/g56-L-07.html", "st": "soon"}, {"id": "초5~6-듣기-08", "g": "초5~6", "a": "듣기", "lv": 2, "n": 8, "t": "천천히 듣고 질문에 답해요", "goal": "교사의 느린 발화를 듣고 이해할 수 있어요.", "std": "교사의 느린 발화를 듣고 이해할 수 있다.", "codes": "L-2-4-1, L-2-4-2, L-2-4-3", "theme": "생활 대화", "acts": ["낱말·표현 익히기: 가방 안에 공책과 필통이 있어요, 오늘은 몇 월 며칠이에요?, 바른 자세로 앉으세요, 큰 소리로 말하세요", "천천히 말한 문장(가방 안에 공책과 필통이 있어요. 등)을 듣고, 문장과 맞는 그림을 고른다.", "천천히 말한 질문(오늘은 몇 월 며칠이에요? 등)을 듣고 답한다.", "확인(진단형) 천천히 말한 지시(바른 자세로 앉으세요. 큰 소리로 말하세요. 등)를 수행한다."], "file": "lessons/g56-L-08.html", "st": "soon"}, {"id": "초5~6-듣기-09", "g": "초5~6", "a": "듣기", "lv": 3, "n": 9, "t": "취미와 가족 여행 이야기를 들어요", "goal": "친숙한 주제에 관한 이야기를 듣고 내용을 파악할 수 있어요.", "std": "친숙한 주제에 관한 이야기를 듣고 내용을 파악할 수 있다.", "codes": "L-3-1-1, L-3-1-2", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 취미, 가족 여행, 학교 행사, 가족 소개, 방과후 활동, 장래희망", "친숙한 주제(취미, 가족 여행, 학교 행사 등)의 이야기를 듣고, 질문에 알맞게 답한다.", "친숙한 주제(가족 소개, 방과후 활동, 장래희망 등)의 이야기를 듣고, 주요 정보를 답한다.", "확인(진단형 L-3-1-1·L-3-1-2 섞기)"], "file": "lessons/g56-L-09.html", "st": "soon"}, {"id": "초5~6-듣기-10", "g": "초5~6", "a": "듣기", "lv": 3, "n": 10, "t": "다음에 일어날 일을 짐작해요", "goal": "대화나 이야기를 듣고 이어질 내용을 짐작할 수 있어요.", "std": "대화나 이야기를 듣고 이어질 내용을 짐작할 수 있다.", "codes": "L-3-2-1, L-3-2-2", "theme": "이야기", "acts": ["낱말·표현 익히기: 날씨: 비가 와요, 추워요, 우산을 가져가요, 두꺼운 옷을 입으세요", "대화(날씨: 비가 와요. 추워요. 등)를 듣고 이어질 내용(우산을 가져가요. 두꺼운 옷을 입으세요. 등)을 짐작해 답한다.", "이야기의 앞부분을 듣고 이어질 내용에 해당하는 그림을 고른다.", "확인(진단형 L-3-2-1·L-3-2-2 섞기)"], "file": "lessons/g56-L-10.html", "st": "soon"}, {"id": "초5~6-듣기-11", "g": "초5~6", "a": "듣기", "lv": 3, "n": 11, "t": "학교 안내와 생활 안내를 들어요", "goal": "일상과 학교생활에서의 안내를 듣고 내용을 파악할 수 있어요.", "std": "일상과 학교생활에서의 안내를 듣고 내용을 파악할 수 있다.", "codes": "L-3-3-1, L-3-3-2", "theme": "학교 행사", "acts": ["낱말·표현 익히기: 현장체험학습, 체육대회, 도서관 규칙, 건강 위생관리, 지역별 일기 예보, 키오스크 사용 방법", "학교생활 안내(현장체험학습, 체육대회, 도서관 규칙, 건강 위생관리 등)를 듣고 내용에 알맞은 그림을 고른다.", "일상생활 안내(지역별 일기 예보, 키오스크 사용 방법, 지역 행사 알림 등)를 듣고 질문에 맞는 그림을 고른다.", "확인(진단형 L-3-3-1·L-3-3-2 섞기)"], "file": "lessons/g56-L-11.html", "st": "soon"}, {"id": "초5~6-듣기-12", "g": "초5~6", "a": "듣기", "lv": 3, "n": 12, "t": "이야기를 듣고 사건 순서를 알아요", "goal": "짧은 이야기를 듣고 대부분의 내용을 파악할 수 있어요.", "std": "짧은 이야기를 듣고 대부분의 내용을 파악할 수 있다.", "codes": "L-3-4-1, L-3-4-2, L-3-4-3, L-3-4-4", "theme": "이야기", "acts": ["낱말·표현 익히기: 3~4문장, 시간, 장소, 학교에서 지낸 이야기, 일상생활 경험", "짧은 이야기(3~4문장)를 듣고 인물과 배경(시간, 장소 등)을 고른다.", "짧은 이야기(학교에서 지낸 이야기, 일상생활 경험 등)를 듣고 일어난 주요 사건을 순서대로 나열한다.", "확인(진단형) 짧은 이야기(학교에서 지낸 이야기, 일상생활 경험 등)를 듣고, 알맞은 내용을 연결한다."], "file": "lessons/g56-L-12.html", "st": "soon"}, {"id": "초5~6-듣기-13", "g": "초5~6", "a": "듣기", "lv": 4, "n": 13, "t": "수업 설명에서 핵심 낱말을 찾아요", "goal": "수업과 관련된 주제의 이야기를 듣고 핵심 내용을 파악할 수 있어요.", "std": "수업과 관련된 주제의 이야기를 듣고 핵심 내용을 파악할 수 있다.", "codes": "L-4-1-1, L-4-1-2, L-4-1-3", "theme": "교과 내용", "acts": ["낱말·표현 익히기: 물질의 상태, 기체, 액체, 고체", "교과 관련 설명(물질의 상태 등)을 듣고, 가장 중요한 개념어(기체, 액체, 고체 등)를 고른다.", "수업 중 시청각 자료를 듣고, 다루고 있는 핵심 내용을 답한다.", "확인(진단형) 교사의 단원 도입 안내를 듣고, 이번 시간에 배울 핵심 목표와 관련된 단어를 찾는다."], "file": "lessons/g56-L-13.html", "st": "soon"}, {"id": "초5~6-듣기-14", "g": "초5~6", "a": "듣기", "lv": 4, "n": 14, "t": "생활 안내를 듣고 주요 내용을 정리해요", "goal": "일상과 학교생활에 관한 내용을 듣고 주요 내용과 세부 내용을 파악할 수 있어요.", "std": "일상과 학교생활에 관한 내용을 듣고 주요 내용과 세부 내용을 파악할 수 있다.", "codes": "L-4-2-1, L-4-2-2, L-4-2-3", "theme": "안전", "acts": ["낱말·표현 익히기: 학교폭력예방수칙, 건강 위생관리, 안전한 학교생활, 언어예절, 공공서비스 이용, 쓰레기 분리배출", "학교생활에 관한 내용(학교폭력예방수칙, 건강 위생관리, 안전한 학교생활, 언어예절 등)을 듣고, 주요 내용과 세부 내용을 찾…", "일상생활에 관한 내용(공공서비스 이용, 쓰레기 분리배출, 에너지 절약 실천방법 등)을 듣고, 주요 내용과 세부 내용을 찾는다.", "확인(진단형) 학교 행사 안내 방송(체육대회 일정 등)을 듣고, 행사의 주요 목적과 세부적인 준비물(단체 티셔츠, 물병 …"], "file": "lessons/g56-L-14.html", "st": "soon"}, {"id": "초5~6-듣기-15", "g": "초5~6", "a": "듣기", "lv": 4, "n": 15, "t": "발표를 듣고 의견과 근거를 찾아요", "goal": "이야기나 발표를 듣고 내용을 파악할 수 있어요.", "std": "이야기나 발표를 듣고 내용을 파악할 수 있다.", "codes": "L-4-3-1, L-4-3-2, L-4-3-3, L-4-3-4", "theme": "발표", "acts": ["낱말·표현 익히기: 책 소개, 위인 소개, 진로, 무엇에 관한 이야기인가요?", "이야기나 발표(책 소개, 위인 소개, 진로 등)를 듣고, 발표 내용과 맞는 그림을 모두 고른다.", "이야기나 발표(책 소개, 위인 소개, 진로 등)를 듣고, 들은 내용에 대한 사실 질문(무엇에 관한 이야기인가요? 등)에 짧게…", "확인(진단형) 발표(점심시간에 휴대폰을 사용하는 것에 대한 발표 등)를 듣고 찬성 혹은 반대 의견을 정확히 구별한다."], "file": "lessons/g56-L-15.html", "st": "soon"}, {"id": "초5~6-듣기-16", "g": "초5~6", "a": "듣기", "lv": 4, "n": 16, "t": "긴 대화에서 상황과 목적을 알아요", "goal": "다소 긴 대화를 듣고 상황과 목적을 파악할 수 있어요.", "std": "다소 긴 대화를 듣고 상황과 목적을 파악할 수 있다.", "codes": "L-4-4-1, L-4-4-2, L-4-4-3", "theme": "대화", "acts": ["낱말·표현 익히기: 청소 구역을 정하며 의견이 충돌하는 상황, 약속을 정하는 대화", "두 사람 간의 갈등이 포함된 긴 대화(청소 구역을 정하며 의견이 충돌하는 상황 등)를 듣고, 대화가 벌어지는 맥락과 각자의 …", "다소 긴 대화나 이야기(약속을 정하는 대화 등)를 듣고 그 상황이나 목적을 답한다.", "확인(진단형) 대화를 듣고 화자가 상대방에게 부탁, 거절, 제안 중 어떤 목적을 가졌는지 파악한다."], "file": "lessons/g56-L-16.html", "st": "soon"}, {"id": "초5~6-말하기-01", "g": "초5~6", "a": "말하기", "lv": 1, "n": 1, "t": "주변의 사물과 날씨를 말해요", "goal": "주변의 사물이나 대상에 대해 짧고 쉬운 단어로 말할 수 있어요.", "std": "주변의 사물이나 대상에 대해 짧고 쉬운 단어로 말할 수 있다.", "codes": "S-1-1-1, S-1-1-2, S-1-1-3, S-1-1-4", "theme": "교실 물건", "acts": ["낱말·표현 익히기: 비, 구름, 해, 책상, 의자, 칠판", "교실 창밖의 풍경이나 날씨(비, 구름, 해 등)를 가리키며 해당되는 단어를 말한다.", "가리키는 교실 사물(책상, 의자, 칠판 등)의 이름을 한 단어로 말한다.", "확인(진단형) 그림 카드를 보고 동물 이름(코끼리, 하마, 기린 등)을 말한다."], "file": "lessons/g56-S-01.html", "st": "soon"}, {"id": "초5~6-말하기-02", "g": "초5~6", "a": "말하기", "lv": 1, "n": 2, "t": "상황에 맞게 인사해요", "goal": "간단한 인사말을 주고받을 수 있어요.", "std": "간단한 인사말을 주고받을 수 있다.", "codes": "S-1-2-1, S-1-2-2, S-1-2-3", "theme": "인사", "acts": ["낱말·표현 익히기: 안녕, 안녕하세요, 잘 가, 고맙습니다, 고마워, 미안합니다", "만나거나 헤어질 때 상황에 맞는 인사(안녕, 안녕하세요, 잘 가 등)를 말한다.", "도움을 받았을 때 상황에 맞는 감사인사(고맙습니다, 고마워 등)를 한다.", "확인(진단형) 실수했을 때 상황에 맞는 사과인사(미안합니다, 미안해 등)를 한다."], "file": "lessons/g56-S-02.html", "st": "soon"}, {"id": "초5~6-말하기-03", "g": "초5~6", "a": "말하기", "lv": 1, "n": 3, "t": "짧게 대답해요", "goal": "간단한 질문에 한두 단어로 대답할 수 있어요.", "std": "간단한 질문에 한두 단어로 대답할 수 있다.", "codes": "S-1-3-1, S-1-3-2, S-1-3-3", "theme": "자기소개", "acts": ["낱말·표현 익히기: 무슨 색깔 좋아해요?, 파란색, 이 지우개 누구 거예요?, 저요, 민수, 화장실 어디 있어요?", "개인의 선호를 묻는 질문(무슨 색깔 좋아해요? 등)에 자신이 좋아하는 대상(파란색 등)을 단어로 답한다.", "소유를 묻는 질문(이 지우개 누구 거예요? 등)에 대상의 주인(저요, 민수 등)을 말한다.", "확인(진단형) 장소나 위치를 묻는 단순한 질문(화장실 어디 있어요? 등)에 방향이나 장소(저기요, 밖 등)를 나타내는 단…"], "file": "lessons/g56-S-03.html", "st": "soon"}, {"id": "초5~6-말하기-04", "g": "초5~6", "a": "말하기", "lv": 1, "n": 4, "t": "아프거나 필요할 때 말해요", "goal": "주요 단어로 의사를 표현할 수 있어요.", "std": "주요 단어로 의사를 표현할 수 있다.", "codes": "S-1-4-1, S-1-4-2, S-1-4-3", "theme": "도움 요청", "acts": ["낱말·표현 익히기: 머리, 배, 가위, 풀, 덥다, 춥다", "신체적 불편함이나 통증이 있을 때, 해당 부위(머리, 배 등)를 말하며 교사에게 도움을 청한다.", "활동 중 특정 도구가 필요할 때, 해당 물건의 이름(가위, 풀 등)을 말하여 요구한다.", "확인(진단형) 덥거나 추울 때, 상태를 나타내는 단어(덥다, 춥다 등)를 말하여 환경 변화를 요청한다."], "file": "lessons/g56-S-04.html", "st": "soon"}, {"id": "초5~6-말하기-05", "g": "초5~6", "a": "말하기", "lv": 1, "n": 5, "t": "천천히 또박또박 말해요", "goal": "부정확하지만 이해할 수 있는 발음과 속도로 천천히 말할 수 있어요.", "std": "부정확하지만 이해할 수 있는 발음과 속도로 천천히 말할 수 있다.", "codes": "S-1-5-1, S-1-5-2", "theme": "발음", "acts": ["낱말·표현 익히기: 핵심 낱말", "발음이 서툴러도 한음절씩 천천히 말한다.", "상대가 알아듣지 못했을 때 같은 말을 다시 천천히 말한다.", "확인(진단형 S-1-5-1·S-1-5-2 섞기)"], "file": "lessons/g56-S-05.html", "st": "soon"}, {"id": "초5~6-말하기-06", "g": "초5~6", "a": "말하기", "lv": 2, "n": 6, "t": "허락을 구하고 부탁해요", "goal": "일상과 학교생활에서 자주 사용하는 문장으로 말할 수 있어요.", "std": "일상과 학교생활에서 자주 사용하는 문장으로 말할 수 있다.", "codes": "S-2-1-1, S-2-1-2, S-2-1-3, S-2-1-4", "theme": "제안·허락", "acts": ["낱말·표현 익히기: 화장실에 다녀와도 돼요?, 지우개 좀 빌려줄래?, 같이 밥 먹자, 모르겠어요, 도와주세요", "허락을 구하는 문장(화장실에 다녀와도 돼요? 등)을 말한다.", "부탁하는 문장(지우개 좀 빌려줄래? 등)을 말한다.", "확인(진단형) 친구에게 제안하는 문장(같이 밥 먹자. 등)을 말한다."], "file": "lessons/g56-S-06.html", "st": "soon"}, {"id": "초5~6-말하기-07", "g": "초5~6", "a": "말하기", "lv": 2, "n": 7, "t": "가족과 좋아하는 과목을 말해요", "goal": "일상생활에서 필요한 질문에 간단한 문장으로 대답할 수 있어요.", "std": "일상생활에서 필요한 질문에 간단한 문장으로 대답할 수 있다.", "codes": "S-2-2-1, S-2-2-2, S-2-2-3", "theme": "가족·소개", "acts": ["낱말·표현 익히기: 어제 집에서 뭐 했어?, 집에서 게임했어요, 형제자매가 어떻게 돼?, 동생이 한 명 있어요, 어떤 과목이 제일 재미있어?, 체육이 제일 재미있어요", "주말이나 방과 후의 일상을 묻는 질문(어제 집에서 뭐 했어? 등)에 자신의 행동 (집에서 게임했어요. 등)을 문장으로 답한다.", "가족 관계나 배경을 묻는 질문(형제자매가 어떻게 돼? 등)에 가족 구성원(동생이 한 명 있어요. 등)을 설명한다.", "확인(진단형) 좋아하는 과목을 묻는 질문(어떤 과목이 제일 재미있어? 등)에 이유를 포함하여(체육이 제일 재미있어요. 등…"], "file": "lessons/g56-S-07.html", "st": "soon"}, {"id": "초5~6-말하기-08", "g": "초5~6", "a": "말하기", "lv": 2, "n": 8, "t": "숙제와 학교 시설을 물어봐요", "goal": "학교생활에서 필요한 정보를 요구하는 질문과 대답을 할 수 있어요.", "std": "학교생활에서 필요한 정보를 요구하는 질문과 대답을 할 수 있다.", "codes": "S-2-3-1, S-2-3-2, S-2-3-3", "theme": "학교생활", "acts": ["낱말·표현 익히기: 이 숙제 언제까지 내요?, 도서관 문 언제 열어?, 다음 시간 어디로 가요?", "과제나 학습 내용의 기한을 확인하기 위해 교사에게 질문(이 숙제 언제까지 내요? 등)을 한다.", "친구에게 학교 시설물의 위치나 이용 시간(도서관 문 언제 열어? 등)을 묻고 답한다.", "확인(진단형) 다음 시간의 교과목이나 이동 장소(다음 시간 어디로 가요? 등)를 주변 친구들에게 물어본다."], "file": "lessons/g56-S-08.html", "st": "soon"}, {"id": "초5~6-말하기-09", "g": "초5~6", "a": "말하기", "lv": 2, "n": 9, "t": "내 느낌과 상태를 말해요", "goal": "간단한 문장으로 의사를 표현할 수 있어요.", "std": "간단한 문장으로 의사를 표현할 수 있다.", "codes": "S-2-4-1, S-2-4-2, S-2-4-3, S-2-4-4, S-2-4-5", "theme": "생각 표현", "acts": ["낱말·표현 익히기: 나는 축구를 좋아합니다, 이 음식은 매워요, 나는 머리가 아파요, 힘들어요, 저거 하고 싶어요, 기다려 주세요", "자신의 선호(나는 축구를 좋아합니다. 등)을 문장으로 말한다.", "자신의 감각이나 느낌(이 음식은 매워요. 등)을 문장으로 표현한다.", "확인(진단형) 자신의 신체적 상태(나는 머리가 아파요. 힘들어요. 등)를 문장으로 말한다."], "file": "lessons/g56-S-09.html", "st": "soon"}, {"id": "초5~6-말하기-10", "g": "초5~6", "a": "말하기", "lv": 2, "n": 10, "t": "일정한 속도로 분명하게 말해요", "goal": "부정확하지만 이해할 수 있는 발음과 속도로 말할 수 있어요.", "std": "부정확하지만 이해할 수 있는 발음과 속도로 말할 수 있다.", "codes": "S-2-5-1, S-2-5-2, S-2-5-3", "theme": "발음", "acts": ["낱말·표현 익히기: 핵심 낱말", "발음이 다소 부정확해도 문장의 전체 의미를 전달한다.", "핵심 어휘의 발음을 이해할 수 있도록 말한다.", "확인(진단형) 너무 빠르지 않은 일정한 속도로 문장을 발화할 수 있다."], "file": "lessons/g56-S-10.html", "st": "soon"}, {"id": "초5~6-말하기-11", "g": "초5~6", "a": "말하기", "lv": 3, "n": 11, "t": "내 취미와 동네를 소개해요", "goal": "친숙한 주제에 관해 말할 수 있어요.", "std": "친숙한 주제에 관해 말할 수 있다.", "codes": "S-3-1-1, S-3-1-2, S-3-1-3", "theme": "좋아하는 것", "acts": ["낱말·표현 익히기: K-pop 댄스, 그림 그리기, 떡볶이집, 문구점, 농구장, 공원", "자신의 취미나 관심사(K-pop 댄스, 그림 그리기 등)에 대해 그 활동을 왜 좋아하는지 2~3문장으로 설명한다.", "자신이 자주 가는 동네의 장소(떡볶이집, 문구점, 농구장, 공원 등)를 소개하며, 그곳의 특징을 이야기한다.", "확인(진단형) 친한 친구를 다른 사람에게 소개할 때, 그 친구의 특징이나 장점(이 친구는 착하고 달리기를 잘해. 등)을 …"], "file": "lessons/g56-S-11.html", "st": "soon"}, {"id": "초5~6-말하기-12", "g": "초5~6", "a": "말하기", "lv": 3, "n": 12, "t": "기억에 남는 일을 말해요", "goal": "겪은 일에 관해 말할 수 있어요.", "std": "겪은 일에 관해 말할 수 있다.", "codes": "S-3-2-1, S-3-2-2, S-3-2-3", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 동물원 견학, 물건을 잃어버린 일, 떨림, 뿌듯함", "현장체험학습이나 여행(동물원 견학 등)에서 가장 인상 깊었던 장면을 설명한다.", "실수나 실패했던 경험(물건을 잃어버린 일 등)을 이야기하며, 실수나 실패하지 않기 위한 다짐을 말한다.", "확인(진단형) 체육대회나 학예회 등 학교 행사에서 자신이 맡았던 역할과 그때 느낀 감정(떨림, 뿌듯함 등)을 말한다."], "file": "lessons/g56-S-12.html", "st": "soon"}, {"id": "초5~6-말하기-13", "g": "초5~6", "a": "말하기", "lv": 3, "n": 13, "t": "수업과 모둠 활동에서 묻고 답해요", "goal": "수업에 참여하여 질문하고 대답할 수 있어요.", "std": "수업에 참여하여 질문하고 대답할 수 있다.", "codes": "S-3-3-1, S-3-3-2, S-3-3-3", "theme": "수업 참여", "acts": ["낱말·표현 익히기: 수학 문제의 풀이 과정, 어려운 낱말이 포함된 안내문, 모둠별 조사하기 활동, 실험 활동", "교사의 열린 질문(우리가 환경을 보호하지 않으면 어떻게 될까? 등)에 대해 자신의 생각을 답한다.", "수업 중 설명이 부족하거나 이해가 가지 않는 부분(수학 문제의 풀이 과정, 어려운 낱말이 포함된 안내문 등)을 질문한다.", "확인(진단형) 짝,모둠 활동 시, 학습 문제(모둠별 조사하기 활동, 실험 활동 등)를 해결하기 위해 서로 알고 있는 내용…"], "file": "lessons/g56-S-13.html", "st": "soon"}, {"id": "초5~6-말하기-14", "g": "초5~6", "a": "말하기", "lv": 3, "n": 14, "t": "공지와 소식을 전해요", "goal": "전해 들은 짧은 이야기를 전달할 수 있어요.", "std": "전해 들은 짧은 이야기를 전달할 수 있다.", "codes": "S-3-4-1, S-3-4-2, S-3-4-3", "theme": "말 전달", "acts": ["낱말·표현 익히기: 준비물, 옆 반에 다른 친구가 전학을 왔다, ~왔다고 했어, 방송 조회, 행사 안내 방송", "한 공지사항(준비물 등)을 결석한 친구에게 정확히 전해준다.", "다른 반 친구에게 들은 소식(옆 반에 다른 친구가 전학을 왔다. 등)을 같은 반 친구에게 왜곡 없이(~왔다고 했어.) 말한다.", "확인(진단형) 학교 방송(방송 조회, 행사 안내 방송 등)에서 들은 핵심 내용 하나를 반 친구들에게 다시 말해준다."], "file": "lessons/g56-S-14.html", "st": "soon"}, {"id": "초5~6-말하기-15", "g": "초5~6", "a": "말하기", "lv": 3, "n": 15, "t": "겹받침과 연음을 바르게 발음해요", "goal": "비교적 정확한 발음으로 말할 수 있어요.", "std": "비교적 정확한 발음으로 말할 수 있다.", "codes": "S-3-5-1, S-3-5-2", "theme": "발음", "acts": ["낱말·표현 익히기: 맑다, 흙, 읽다, 밝다, 넓다, 놀이터", "겹받침(맑다, 흙, 읽다, 밝다, 넓다 등)이나 연음 법칙(놀이터, 줄넘기, 책꽂이 등)이 적용되는 단어를 비교적 정확하게 …", "목소리 크기를 상황(둘이 말할 때, 여러 사람 앞에서 말할 때 등)에 맞게 조절하여 또렷하게 발음한다.", "확인(진단형 S-3-5-1·S-3-5-2 섞기)"], "file": "lessons/g56-S-15.html", "st": "soon"}, {"id": "초5~6-말하기-16", "g": "초5~6", "a": "말하기", "lv": 4, "n": 16, "t": "작품과 뉴스에 대한 생각을 말해요", "goal": "수업 내용과 관련된 다양한 주제에 관해 말할 수 있어요.", "std": "수업 내용과 관련된 다양한 주제에 관해 말할 수 있다.", "codes": "S-4-1-1, S-4-1-2", "theme": "생각 표현", "acts": ["낱말·표현 익히기: 소설, 시, 주인공의 행동은 옳지 않다고 생각합니다, 왜냐하면, 기후 위기", "문학 작품(소설, 시 등)을 감상한 후, 작품 속 인물의 행동에 대한 자신의 가치 판단(주인공의 행동은 옳지 않다고 생각합니…", "시사 문제나 뉴스 기사(기후 위기 등) 속 문제의 원인과 해결책에 대한 자신의 생각을 말한다.", "확인(진단형 S-4-1-1·S-4-1-2 섞기)"], "file": "lessons/g56-S-16.html", "st": "soon"}, {"id": "초5~6-말하기-17", "g": "초5~6", "a": "말하기", "lv": 4, "n": 17, "t": "글과 영상을 요약해서 말해요", "goal": "정보를 요약하여 말할 수 있어요.", "std": "정보를 요약하여 말할 수 있다.", "codes": "S-4-2-1, S-4-2-2", "theme": "요약", "acts": ["낱말·표현 익히기: 안내장, 신청서, 화재 대피 요령 영상", "한 페이지 분량의 글(안내장, 신청서 등)을 읽고 가장 중요한 핵심 내용 2~3가지를 말한다.", "교육용 영상(화재 대피 요령 영상 등)을 본 후 전체적인 줄거리를 친구에게 설명한다.", "확인(진단형 S-4-2-1·S-4-2-2 섞기)"], "file": "lessons/g56-S-17.html", "st": "soon"}, {"id": "초5~6-말하기-18", "g": "초5~6", "a": "말하기", "lv": 4, "n": 18, "t": "수업 내용을 발표해요", "goal": "수업에 참여하여 수업 내용에 관해 발표할 수 있어요.", "std": "수업에 참여하여 수업 내용에 관해 발표할 수 있다.", "codes": "S-4-3-1", "theme": "발표", "acts": ["낱말·표현 익히기: 실험 방법, 생태 전환, 사회 현상, 세계 문화", "수업 내용(실험 방법, 생태 전환, 사회 현상, 세계 문화 등)과 관련된 주제에 대해 자신의 말로 표현한다.", "같은 방식, 소재를 바꿔 한 번 더", "확인(진단형 S-4-3-1)"], "file": "lessons/g56-S-18.html", "st": "soon"}, {"id": "초5~6-말하기-19", "g": "초5~6", "a": "말하기", "lv": 4, "n": 19, "t": "고민을 상담하고 갈등을 풀어요", "goal": "상황과 목적에 맞게 다소 긴 대화를 할 수 있어요.", "std": "상황과 목적에 맞게 다소 긴 대화를 할 수 있다.", "codes": "S-4-4-1, S-4-4-2, S-4-4-3", "theme": "대화", "acts": ["낱말·표현 익히기: 중학교 진학, 성적 고민, 한국어 공부, 핸드폰, 가방, 친구가 나를 밀었을 때", "교사에게 진로(중학교 진학 등)나 학업(성적 고민, 한국어 공부 등)에 대한 조언을 구하며 질문과 대답을 주고받는 긴 대화를…", "물건(핸드폰, 가방 등)을 잃어버렸을 때 분실물 센터나 교무실에 가서 잃어버린 상황을 설명하며 대화한다.", "확인(진단형) 갈등 상황(친구가 나를 밀었을 때, 물을 엎질렀을 때 등)을 해결하기 위해 자신의 감정과 이유를 설명하며 …"], "file": "lessons/g56-S-19.html", "st": "soon"}, {"id": "초5~6-말하기-20", "g": "초5~6", "a": "말하기", "lv": 4, "n": 20, "t": "자리와 상대에 맞게 말해요", "goal": "대화 상대와 맥락을 고려하여 자연스럽게 말할 수 있어요.", "std": "대화 상대와 맥락을 고려하여 자연스럽게 말할 수 있다.", "codes": "S-4-5-1, S-4-5-2, S-4-5-3", "theme": "높임말", "acts": ["낱말·표현 익히기: 학급 회의, 친구와의 대화, 호응어", "교사나 웃어른에게 말할 때와 친구에게 말할 때의 높임법을 정확히 구분하여 사용한다.", "공식적인 자리(학급 회의 등)와 비공식적인 자리(친구와의 대화 등)에서 상황에 따른 언어예절을 지켜 말한다.", "확인(진단형) 대화의 흐름이 끊기지 않도록 맞장구(호응어 등)를 적절히 사용하며 자연스럽게 대화에 참여한다."], "file": "lessons/g56-S-20.html", "st": "soon"}, {"id": "초5~6-읽기-01", "g": "초5~6", "a": "읽기", "lv": 1, "n": 1, "t": "생활 속 낱말과 달력을 읽어요", "goal": "글자와 단어를 소리 내어 읽을 수 있어요.", "std": "글자와 단어를 소리 내어 읽을 수 있다.", "codes": "R-1-1-1, R-1-1-2, R-1-1-3", "theme": "한글 자모", "acts": ["낱말·표현 익히기: 학교, 가방, 월, 화, 수, 일", "생활 속에서 자주 보는 친숙한 단어(학교, 가방 등)를 보고 읽는다.", "요일(월, 화, 수 등)과 숫자(일, 이, 삼 등)가 적힌 달력을 소리 내어 읽는다.", "확인(진단형) 알림장의 내용 중 과목명(실과, 영어 등)이나 짧은 단어 단위의 공지사항(준비물, 체육대회, 모자 등)을 …"], "file": "lessons/g56-R-01.html", "st": "soon"}, {"id": "초5~6-읽기-02", "g": "초5~6", "a": "읽기", "lv": 1, "n": 2, "t": "낱말을 읽고 알맞은 것을 찾아요", "goal": "짧고 쉬운 단어를 읽고 의미를 파악할 수 있어요.", "std": "짧고 쉬운 단어를 읽고 의미를 파악할 수 있다.", "codes": "R-1-2-1, R-1-2-2, R-1-2-3", "theme": "교실 물건", "acts": ["낱말·표현 익히기: 가위, 풀, 코뿔소, 표범, 치타, 원숭이", "사물의 이름(가위, 풀 등)을 읽고, 해당 물건을 정확히 찾는다.", "동물 이름 카드(코뿔소, 표범, 치타, 원숭이 등)를 읽고 해당하는 동물의 사진을 정확히 찾는다.", "확인(진단형) 반대되는 의미를 가진 단어 쌍(크다-작다 등)이 적힌 카드를 읽고, 알맞은 쌍끼리 짝을 지어 분류한다."], "file": "lessons/g56-R-02.html", "st": "soon"}, {"id": "초5~6-읽기-03", "g": "초5~6", "a": "읽기", "lv": 1, "n": 3, "t": "식단표와 경고문을 읽어요", "goal": "일상과 학교생활에서 사용하는 안내/간판 등의 내용을 파악할 수 있어요.", "std": "일상과 학교생활에서 사용하는 안내/간판 등의 내용을 파악할 수 있다.", "codes": "R-1-3-1, R-1-3-2, R-1-3-3", "theme": "학교생활", "acts": ["낱말·표현 익히기: 약국, 병원, 보건실, 화장실, 김치, 우유", "표지판, 간판에 쓰여진 어휘(약국, 병원, 보건실, 화장실 등)를 읽고, 목적지를 찾는다.", "급식 식단표에 쓰인 음식 이름(김치, 우유 등)을 읽고, 오늘 자신이 먹게 될 주요 메뉴를 파악한다.", "확인(진단형) 경고문(뛰지 마시오, 멈추시오, 기대지 마시오 등)을 읽고 해당하는 픽토그램을 찾는다."], "file": "lessons/g56-R-03.html", "st": "soon"}, {"id": "초5~6-읽기-04", "g": "초5~6", "a": "읽기", "lv": 1, "n": 4, "t": "받침과 비슷한 글자를 구별해 읽어요", "goal": "한글 자음과 모음, 받침 등 글자를 식별하여 짧은 문장을 읽을 수 있어요.", "std": "한글 자음과 모음, 받침 등 글자를 식별하여 짧은 문장을 읽을 수 있다.", "codes": "R-1-4-1, R-1-4-2", "theme": "한글 자모", "acts": ["낱말·표현 익히기: 가방 안에 공이 있어요, 엄마가 밥을 만들어요, 연필이 책상 위에 있어요, 고, 교, 발", "받침이 있는 글자가 포함된 짧은 문장(가방 안에 공이 있어요. 엄마가 밥을 만들어요. 연필이 책상 위에 있어요 등)을 비교적…", "글자 모양이 비슷한 글자들(고/교, 발/방 등)이 포함된 짧은 문장을 눈으로 식별하여 정확한 소릿값으로 읽는다.", "확인(진단형 R-1-4-1·R-1-4-2 섞기)"], "file": "lessons/g56-R-04.html", "st": "soon"}, {"id": "초5~6-읽기-05", "g": "초5~6", "a": "읽기", "lv": 2, "n": 5, "t": "문장부호를 살려 읽어요", "goal": "문장을 알맞게 띄어 읽을 수 있어요.", "std": "문장을 알맞게 띄어 읽을 수 있다.", "codes": "R-2-1-1, R-2-1-2, R-2-1-3", "theme": "문장", "acts": ["낱말·표현 익히기: 핵심 낱말", "문장의 띄어쓰기 단위 또는 어절에 맞춰 적절한 간격을 두어 읽는다.", "마침표(.)가 있는 곳에서 문장이 끝났음을 인지하고 충분히 쉬어 읽는다.", "확인(진단형) 쉼표(,)가 있는 곳에서 살짝 쉬어 읽으며 문맥을 연결한다."], "file": "lessons/g56-R-05.html", "st": "soon"}, {"id": "초5~6-읽기-06", "g": "초5~6", "a": "읽기", "lv": 2, "n": 6, "t": "문장을 읽고 뜻을 알아요", "goal": "문장의 의미를 대강 파악할 수 있어요.", "std": "문장의 의미를 대강 파악할 수 있다.", "codes": "R-2-2-1, R-2-2-2, R-2-2-3", "theme": "교과서", "acts": ["낱말·표현 익히기: 친구가 운동장에서 축구를 합니다, 도서관에서는 조용히 책을 읽습니다, 글을 읽고 중심 문장을 찾아봅시다, 중심 문장 찾기", "문장(친구가 운동장에서 축구를 합니다. 등)을 읽고, 누가, 무엇을 하는지 알맞은 그림을 고른다.", "장소에 따른 주의사항(도서관에서는 조용히 책을 읽습니다. 등)을 읽고, 문장의 내용에 알맞은 그림에 표시한다.", "확인(진단형) 교과서의 학습 목표(글을 읽고 중심 문장을 찾아봅시다. 등)를 읽고 오늘 배울 내용(중심 문장 찾기 등)이…"], "file": "lessons/g56-R-06.html", "st": "soon"}, {"id": "초5~6-읽기-07", "g": "초5~6", "a": "읽기", "lv": 2, "n": 7, "t": "안내문과 광고문에서 정보를 찾아요", "goal": "안내문, 광고문 등의 글을 읽고 정보를 찾을 수 있어요.", "std": "안내문, 광고문 등의 글을 읽고 정보를 찾을 수 있다.", "codes": "R-2-3-1, R-2-3-2", "theme": "학교 행사", "acts": ["낱말·표현 익히기: 특산물 광고, 상품명, 파는 곳, 가격, 종류, 체육 대회", "광고문(특산물 광고 등)을 읽고 필요한 정보(상품명, 파는 곳, 가격, 종류 등)를 골라낸다.", "안내문(체육 대회 등)을 읽고, 명확한 정보를 찾아내어 알림장(날짜, 시간, 준비물 등)에 옮겨 적는다.", "확인(진단형 R-2-3-1·R-2-3-2 섞기)"], "file": "lessons/g56-R-07.html", "st": "soon"}, {"id": "초5~6-읽기-08", "g": "초5~6", "a": "읽기", "lv": 2, "n": 8, "t": "이어진 문장을 끊어 읽어요", "goal": "다양한 구조의 문장을 의미 단위로 끊어 읽을 수 있어요.", "std": "다양한 구조의 문장을 의미 단위로 끊어 읽을 수 있다.", "codes": "R-2-4-1, R-2-4-2, R-2-4-3, R-2-4-4", "theme": "문장", "acts": ["낱말·표현 익히기: 동생은 v 귀여워요, 크고 맛있는 사과", "문장(동생은 v 귀여워요 등)을 주어와 서술어로 나누어 적절히 끊어 읽는다.", "꾸며주는 말이 포함된 구(크고 맛있는 사과 등)를 하나의 의미 단위로 읽는다.", "확인(진단형) 이어주는 말(-고, -거나, -이어서, -해서 등)이 있는 문장을 앞 절과 뒤 절로 끊어 읽을 수 있다."], "file": "lessons/g56-R-08.html", "st": "soon"}, {"id": "초5~6-읽기-09", "g": "초5~6", "a": "읽기", "lv": 3, "n": 9, "t": "취미에 관한 글을 읽어요", "goal": "친숙한 주제의 글을 읽고 대강의 내용을 파악할 수 있어요.", "std": "친숙한 주제의 글을 읽고 대강의 내용을 파악할 수 있다.", "codes": "R-3-1-1, R-3-1-2", "theme": "좋아하는 것", "acts": ["낱말·표현 익히기: K-pop 댄스, 그림 그리기, 취미 생활", "친숙한 주제(K-pop 댄스, 그림 그리기, 취미 생활 등)의 글을 읽고, 내용에 맞는 그림을 고른다.", "친숙한 주제(K-pop 댄스, 그림 그리기, 취미 생활 등)의 글을 읽고, 주요 정보를 답한다.", "확인(진단형 R-3-1-1·R-3-1-2 섞기)"], "file": "lessons/g56-R-09.html", "st": "soon"}, {"id": "초5~6-읽기-10", "g": "초5~6", "a": "읽기", "lv": 3, "n": 10, "t": "사실과 의견을 구분해요", "goal": "글을 읽고 사실과 생각이나 느낌을 구분할 수 있어요.", "std": "글을 읽고 사실과 생각이나 느낌을 구분할 수 있다.", "codes": "R-3-2-1, R-3-2-2", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 기행문, 체험활동 보고서, 일기, 감상문", "글(기행문, 체험활동 보고서 등)을 읽고 사실과 생각이나 느낌을 구분한다.", "글(일기, 감상문 등)을 읽고 글쓴이의 개인적인 의견이나 느낌이 담긴 문장을 찾는다.", "확인(진단형 R-3-2-1·R-3-2-2 섞기)"], "file": "lessons/g56-R-10.html", "st": "soon"}, {"id": "초5~6-읽기-11", "g": "초5~6", "a": "읽기", "lv": 3, "n": 11, "t": "설명하는 글과 이야기를 읽어요", "goal": "이야기나 설명하는 글을 읽고 주요 내용을 파악할 수 있어요.", "std": "이야기나 설명하는 글을 읽고 주요 내용을 파악할 수 있다.", "codes": "R-3-3-1, R-3-3-2", "theme": "교과 내용", "acts": ["낱말·표현 익히기: 대상의 생김새, 사는 곳, 먹이, 시간, 장소", "설명문을 읽고 3가지 이상 주요 특징(대상의 생김새, 사는 곳, 먹이 등)을 찾는다.", "이야기를 읽고 인물과 배경(시간, 장소 등)을 고른다.", "확인(진단형 R-3-3-1·R-3-3-2 섞기)"], "file": "lessons/g56-R-11.html", "st": "soon"}, {"id": "초5~6-읽기-12", "g": "초5~6", "a": "읽기", "lv": 3, "n": 12, "t": "문단의 중심 문장을 찾아요", "goal": "한 문단을 읽고 내용을 파악할 수 있어요.", "std": "한 문단을 읽고 내용을 파악할 수 있다.", "codes": "R-3-4-1, R-3-4-2", "theme": "중심 내용", "acts": ["낱말·표현 익히기: 자연 보호, 언어 예절, 바른 말과 고운 말을 씁시다", "하나의 문단을 읽고 그 문단의 소주제 또는 제목(자연 보호 등)을 정한다.", "중심 문장과 뒷받침 문장으로 이루어진 문단(언어 예절 등)을 읽고, 핵심 주장(바른 말과 고운 말을 씁시다. 등)만 포함된 …", "확인(진단형 R-3-4-1·R-3-4-2 섞기)"], "file": "lessons/g56-R-12.html", "st": "soon"}, {"id": "초5~6-읽기-13", "g": "초5~6", "a": "읽기", "lv": 4, "n": 13, "t": "여러 주제의 글을 비교하며 읽어요", "goal": "다양한 주제의 글을 읽고 내용을 파악할 수 있어요.", "std": "다양한 주제의 글을 읽고 내용을 파악할 수 있다.", "codes": "R-4-1-1, R-4-1-2, R-4-1-3", "theme": "문화", "acts": ["낱말·표현 익히기: 한국문화, 온라인 언어폭력, 약물 오남용, 인공지능, 추수감사절, 춘절과 추석", "다양한 주제의 글(한국문화, 온라인 언어폭력, 약물 오남용 등)을 읽고 중심내용을 찾는다.", "다양한 주제의 글(인공지능 등)을 읽고 대상의 장점과 단점을 비교한다.", "확인(진단형) 다른 나라의 문화나 축제(추수감사절, 춘절과 추석 등)에 관한 글을 읽고 우리나라 문화와 비교한다."], "file": "lessons/g56-R-13.html", "st": "soon"}, {"id": "초5~6-읽기-14", "g": "초5~6", "a": "읽기", "lv": 4, "n": 14, "t": "앞뒤를 보고 짐작하며 읽어요", "goal": "글을 읽고 의미나 내용을 추론할 수 있어요.", "std": "글을 읽고 의미나 내용을 추론할 수 있다.", "codes": "R-4-2-1, R-4-2-2, R-4-2-3", "theme": "이야기", "acts": ["낱말·표현 익히기: 전래 동화, 이솝 우화, 얼굴이 찡그려지다, 손을 부르르 떨다, 증발, 물이 끓어서 증발해서 물이 줄어들었어요", "글(전래 동화, 이솝 우화 등)을 읽고 다음에 이어질 이야기를 짐작하여 고른다.", "비언어적 묘사(얼굴이 찡그려지다. 손을 부르르 떨다. 등)를 읽고, 인물의 마음을 추측한다.", "확인(진단형) 모르는 어휘(증발 등)가 나왔을 때 문맥(물이 끓어서 증발해서 물이 줄어들었어요. 등)을 통해 단어의 대략…"], "file": "lessons/g56-R-14.html", "st": "soon"}, {"id": "초5~6-읽기-15", "g": "초5~6", "a": "읽기", "lv": 4, "n": 15, "t": "설명서와 주장하는 글을 읽어요", "goal": "교과서에 나오는 다양한 형식의 글을 읽고 주요 내용을 파악할 수 있어요.", "std": "교과서에 나오는 다양한 형식의 글을 읽고 주요 내용을 파악할 수 있다.", "codes": "R-4-3-1, R-4-3-2", "theme": "교과서", "acts": ["낱말·표현 익히기: 사용설명서, 레시피, 공지사항, 자기소개서, 공익광고 글", "정보를 전달하는 글(사용설명서, 레시피, 공지사항, 자기소개서 등)을 읽고 핵심 내용을 찾는다.", "주장하는 글(공익광고 글 등)을 읽고 주장과 근거를 고른다.", "확인(진단형 R-4-3-1·R-4-3-2 섞기)"], "file": "lessons/g56-R-15.html", "st": "soon"}, {"id": "초5~6-읽기-16", "g": "초5~6", "a": "읽기", "lv": 4, "n": 16, "t": "글의 구조를 파악해요", "goal": "다양한 유형의 글을 읽고 내용의 흐름을 파악할 수 있어요.", "std": "다양한 유형의 글을 읽고 내용의 흐름을 파악할 수 있다.", "codes": "R-4-4-1, R-4-4-2", "theme": "중심 내용", "acts": ["낱말·표현 익히기: 이야기, 설명하는 글, 전기문, 기행문, 대본, 서론-본론-결론", "글(이야기, 설명하는 글, 전기문, 기행문, 대본 등)을 읽고 요약된 문장을 순서대로 배열한다.", "글의 구조(서론-본론-결론 등)에 따라 글의 순서를 배치한다.", "확인(진단형 R-4-4-1·R-4-4-2 섞기)"], "file": "lessons/g56-R-16.html", "st": "soon"}, {"id": "초5~6-쓰기-01", "g": "초5~6", "a": "쓰기", "lv": 1, "n": 1, "t": "글자와 낱말을 써요", "goal": "글자와 단어를 쓸 수 있어요.", "std": "글자와 단어를 쓸 수 있다.", "codes": "W-1-1-1, W-1-1-2, W-1-1-3", "theme": "한글 자모", "acts": ["낱말·표현 익히기: 가, 나, 다, 사과, 우유, 책", "제시한 글자(가, 나, 다 등)를 보고 같은 글자를 쓴다.", "그림 옆에 제시된 낱말(사과, 우유, 책 등)을 쓴다.", "확인(진단형) 일상생활에서 자주 보는 단어(책, 학교, 가방 등)를 쓴다."], "file": "lessons/g56-W-01.html", "st": "soon"}, {"id": "초5~6-쓰기-02", "g": "초5~6", "a": "쓰기", "lv": 1, "n": 2, "t": "획순과 모양에 맞게 써요", "goal": "필순과 자형에 맞게 글자를 쓸 수 있어요.", "std": "필순과 자형에 맞게 글자를 쓸 수 있다.", "codes": "W-1-2-1, W-1-2-2, W-1-2-3", "theme": "한글 자모", "acts": ["낱말·표현 익히기: ㄹ, ㅂ, ㅍ, 필순, 'ㅏ'의 짧은 가로획, 각", "헷갈리기 쉬운 자음(ㄹ, ㅂ, ㅍ 등)을 획순(필순)에 맞게 쓴다.", "모음의 획('ㅏ'의 짧은 가로획 등)을 명확하게 그어, 다른 모음과 혼동되지 않도록 또박또박 쓴다.", "확인(진단형) 받침이 있는 글자(각, 국, 산 등)를 쓸 때 위아래 균형을 맞추어 반듯한 모양(자형)으로 쓴다."], "file": "lessons/g56-W-02.html", "st": "soon"}, {"id": "초5~6-쓰기-03", "g": "초5~6", "a": "쓰기", "lv": 1, "n": 3, "t": "나를 소개하고 인사 카드를 써요", "goal": "인사말이나 간단한 신상 정보(이름, 나이 등)를 쓸 수 있어요.", "std": "인사말이나 간단한 신상 정보(이름, 나이 등)를 쓸 수 있다.", "codes": "W-1-3-1, W-1-3-2, W-1-3-3", "theme": "자기소개", "acts": ["낱말·표현 익히기: 필리핀, 베트남, 키르기스스탄, 카자흐스탄, 중국, 이름", "자신의 출신 국가(필리핀, 베트남, 키르기스스탄, 카자흐스탄, 중국 등)를 한글로 쓴다.", "자신과 관련된 정보(이름, 나이, 학교 이름, 학년 반 등)를 찾아 쓴다.", "확인(진단형) 특정 상황(생일, 사과, 감사 등)에 맞는 인사말(생일 축하해, 미안해, 고마워 등)을 담은 카드를 적는다."], "file": "lessons/g56-W-03.html", "st": "soon"}, {"id": "초5~6-쓰기-04", "g": "초5~6", "a": "쓰기", "lv": 1, "n": 4, "t": "그림을 보고 낱말을 써요", "goal": "시각 자료를 보고 해당하는 단어를 쓸 수 있어요.", "std": "시각 자료를 보고 해당하는 단어를 쓸 수 있다.", "codes": "W-1-4-1", "theme": "교실 물건", "acts": ["낱말·표현 익히기: 해, 우산", "그림(해, 우산 등)을 보고 알맞은 낱말을 쓴다.", "같은 방식, 소재를 바꿔 한 번 더", "확인(진단형 W-1-4-1)"], "file": "lessons/g56-W-04.html", "st": "soon"}, {"id": "초5~6-쓰기-05", "g": "초5~6", "a": "쓰기", "lv": 2, "n": 5, "t": "기본 문장을 써요", "goal": "단어와 문장을 쓸 수 있어요.", "std": "단어와 문장을 쓸 수 있다.", "codes": "W-2-1-1, W-2-1-2", "theme": "문장", "acts": ["낱말·표현 익히기: 나는 6학년입니다, 나, 사과, 먹다, 나는 사과를 먹습니다", "주어와 서술어를 갖춘 완전한 문장(나는 6학년입니다. 등)을 쓴다.", "알고 있는 단어 여러 개(나, 사과, 먹다 등)를 연결하여 기본 문장 구조(나는 사과를 먹습니다. 등)를 만든다.", "확인(진단형 W-2-1-1·W-2-1-2 섞기)"], "file": "lessons/g56-W-05.html", "st": "soon"}, {"id": "초5~6-쓰기-06", "g": "초5~6", "a": "쓰기", "lv": 2, "n": 6, "t": "문장을 바꾸어 써요", "goal": "문장의 내용을 부분적으로 바꾸어 쓸 수 있어요.", "std": "문장의 내용을 부분적으로 바꾸어 쓸 수 있다.", "codes": "W-2-2-1, W-2-2-2", "theme": "문장", "acts": ["낱말·표현 익히기: 비가 옵니다, 비가 안 옵니다, 또는 비가 오지 않습니다, 나는 ~에서 ~을 했습니다", "긍정문(비가 옵니다. 등)을 부정문(비가 안 옵니다. 또는 비가 오지 않습니다. 등)의 형태로 바꿔 쓴다.", "빈칸이 주어진 문장 형식(나는 ~에서 ~을 했습니다. 등)에 맞게 자신의 경험을 적는다.", "확인(진단형 W-2-2-1·W-2-2-2 섞기)"], "file": "lessons/g56-W-06.html", "st": "soon"}, {"id": "초5~6-쓰기-07", "g": "초5~6", "a": "쓰기", "lv": 2, "n": 7, "t": "겪은 일을 이어서 써요", "goal": "겪은 일을 여러 개의 문장으로 쓸 수 있어요.", "std": "겪은 일을 여러 개의 문장으로 쓸 수 있다.", "codes": "W-2-3-1, W-2-3-2", "theme": "겪은 일", "acts": ["낱말·표현 익히기: 방학동안 한 일, 주말 지낸 이야기, 가족 여행", "겪은 일(방학동안 한 일, 주말 지낸 이야기, 가족 여행 등)을 2~3개의 문장으로 이어지게 쓴다.", "경험(방학동안 한 일, 주말 지낸 이야기, 가족 여행 등)에 대한 원인과 결과, 감정 등을 포함하여 3문장 정도로 쓴다.", "확인(진단형 W-2-3-1·W-2-3-2 섞기)"], "file": "lessons/g56-W-07.html", "st": "soon"}, {"id": "초5~6-쓰기-08", "g": "초5~6", "a": "쓰기", "lv": 2, "n": 8, "t": "용건과 알림장을 메모해요", "goal": "일상과 학교생활에서 필요한 간단한 메모를 할 수 있어요.", "std": "일상과 학교생활에서 필요한 간단한 메모를 할 수 있다.", "codes": "W-2-4-1, W-2-4-2", "theme": "학교생활", "acts": ["낱말·표현 익히기: 나 화장실 갔다 올게, 서준이가 찾아왔었어, 점심시간에 만나, 알림장", "친구에게 전할 짧은 용건(나 화장실 갔다 올게. 서준이가 찾아왔었어. 점심시간에 만나. 등)을 메모한다.", "필요한 정보(알림장 등)를 요약하여 적는다.", "확인(진단형 W-2-4-1·W-2-4-2 섞기)"], "file": "lessons/g56-W-08.html", "st": "soon"}, {"id": "초5~6-쓰기-09", "g": "초5~6", "a": "쓰기", "lv": 3, "n": 9, "t": "생각과 느낌을 살려 써요", "goal": "생각이나 느낌이 잘 드러나는 글을 쓸 수 있어요.", "std": "생각이나 느낌이 잘 드러나는 글을 쓸 수 있다.", "codes": "W-3-1-1, W-3-1-2, W-3-1-3", "theme": "마음 전하기", "acts": ["낱말·표현 익히기: 속상했다, 뿌듯했다, 미운 오리 새끼가 백조가 되는 장면, 주인공에게 친구가 생겨서, 이젠 혼자가 아니라서, 감사", "경험과 그에 대한 감정(속상했다, 뿌듯했다 등)을 구체적인 단어를 사용해 일기를 쓴다.", "감명 깊었던 장면(미운 오리 새끼가 백조가 되는 장면 등)과 그 이유(주인공에게 친구가 생겨서, 이젠 혼자가 아니라서 등)를…", "확인(진단형) 자신의 생각(감사, 사과, 요청, 제안 등)을 담아 편지를 쓴다."], "file": "lessons/g56-W-09.html", "st": "soon"}, {"id": "초5~6-쓰기-10", "g": "초5~6", "a": "쓰기", "lv": 3, "n": 10, "t": "조사와 높임말을 바르게 써요", "goal": "어느 정도 어법에 맞게 단어나 문장을 쓸 수 있어요.", "std": "어느 정도 어법에 맞게 단어나 문장을 쓸 수 있다.", "codes": "W-3-2-1, W-3-2-2, W-3-2-3", "theme": "높임말", "acts": ["낱말·표현 익히기: 은, 는, 이, 가, 을, 를", "기본적인 조사(은/는, 이/가, 을/를 등)를 문맥과 앞 단어의 받침 유무에 맞게 쓴다.", "높임말(주무시다. 드시다. 계시다. 생신, 연세, 진지 등)을 알맞게 사용한다.", "확인(진단형) 문장의 시제(어제 ~했다, 오늘 ~한다, 내일 ~할 것이다 등)에 맞게 서술어의 형태를 변형한다."], "file": "lessons/g56-W-10.html", "st": "soon"}, {"id": "초5~6-쓰기-11", "g": "초5~6", "a": "쓰기", "lv": 3, "n": 11, "t": "좋아하는 것을 설명하는 글을 써요", "goal": "친숙한 대상이나 사물에 관해 설명하는 글을 쓸 수 있어요.", "std": "친숙한 대상이나 사물에 관해 설명하는 글을 쓸 수 있다.", "codes": "W-3-3-1", "theme": "좋아하는 것", "acts": ["낱말·표현 익히기: 아이돌, 굿즈, 게임, 취미 활동, 교우 관계", "친숙한 대상이나 사물(아이돌, 굿즈, 게임, 취미 활동, 교우 관계 등)에 관해 구체적 특징을 들어 알기 쉽게 설명하는 글을…", "같은 방식, 소재를 바꿔 한 번 더", "확인(진단형 W-3-3-1)"], "file": "lessons/g56-W-11.html", "st": "soon"}, {"id": "초5~6-쓰기-12", "g": "초5~6", "a": "쓰기", "lv": 3, "n": 12, "t": "친구들에게 정보를 알리는 글을 써요", "goal": "일상과 학교생활에서 필요한 정보를 전달하는 글을 간략하게 쓸 수 있어요.", "std": "일상과 학교생활에서 필요한 정보를 전달하는 글을 간략하게 쓸 수 있다.", "codes": "W-3-4-1, W-3-4-2", "theme": "학교 행사", "acts": ["낱말·표현 익히기: 숙제 기한, 공공시설 이용, 공익 광고, 인터넷 게시글, 메세지, 게시판 안내글", "친구들에게 필요한 정보(숙제 기한, 공공시설 이용 등)를 전달하는 글을 쓴다.", "필요한 정보를 전달하는 글(공익 광고, 인터넷 게시글, 메세지, 게시판 안내글 등)을 쓴다.", "확인(진단형 W-3-4-1·W-3-4-2 섞기)"], "file": "lessons/g56-W-12.html", "st": "soon"}, {"id": "초5~6-쓰기-13", "g": "초5~6", "a": "쓰기", "lv": 4, "n": 13, "t": "주제를 정해 글을 써요", "goal": "주제를 정하여 글을 쓸 수 있어요.", "std": "주제를 정하여 글을 쓸 수 있다.", "codes": "W-4-1-1, W-4-1-2", "theme": "주제 글쓰기", "acts": ["낱말·표현 익히기: 환경 보호, 인공지능, 에너지 절약, 로봇의 발전, 기후 위기, 언어 예절 지키기", "제시한 여러 큰 범주(환경 보호, 인공지능 등) 중 하나를 선택하여, 구체적인 소주제(에너지 절약, 로봇의 발전 등)를 정해…", "주제(에너지 절약, 기후 위기, 로봇의 발전, 환경 보호, 언어 예절 지키기 등)에서 벗어나지 않고 처음부터 끝까지 관련 있…", "확인(진단형 W-4-1-1·W-4-1-2 섞기)"], "file": "lessons/g56-W-13.html", "st": "soon"}, {"id": "초5~6-쓰기-14", "g": "초5~6", "a": "쓰기", "lv": 4, "n": 14, "t": "맞춤법과 띄어쓰기를 지켜 써요", "goal": "어법에 맞게 문장을 쓸 수 있어요.", "std": "어법에 맞게 문장을 쓸 수 있다.", "codes": "W-4-2-1, W-4-2-2, W-4-2-3, W-4-2-4", "theme": "문장", "acts": ["낱말·표현 익히기: 낳다, 낫다, 않다, 안다, 가르치다, 가리키다", "자주 틀리는 기본적인 맞춤법(낳다/낫다, 않다/안다, 가르치다/가리키다, 잃다/잊다, 맞히다/맞추다 등)을 구별한다.", "띄어쓰기에 맞게 문장(책 세 권을 빌렸어요. 등)을 쓸 수 있다.", "확인(진단형) 주어와 서술어의 호응 관계(내가 바라는 것은 ~이다 등)가 어긋나지 않도록 쓴다."], "file": "lessons/g56-W-14.html", "st": "soon"}, {"id": "초5~6-쓰기-15", "g": "초5~6", "a": "쓰기", "lv": 4, "n": 15, "t": "근거를 들어 주장하는 글을 써요", "goal": "이유나 근거를 들어 주장하는 글을 쓸 수 있어요.", "std": "이유나 근거를 들어 주장하는 글을 쓸 수 있다.", "codes": "W-4-3-1, W-4-3-2", "theme": "생각 표현", "acts": ["낱말·표현 익히기: 에너지 절약, 기후 위기, 환경 보호, 사실, 통계, 혹은 객관적인 경험", "주제(에너지 절약, 기후 위기, 환경 보호 등)에 대해 자신의 입장을 정하고, 근거를 덧붙여 글을 작성한다.", "주장을 뒷받침하기 위해 신뢰할 수 있는 자료(사실, 통계, 혹은 객관적인 경험 등)을 근거로 든다.", "확인(진단형 W-4-3-1·W-4-3-2 섞기)"], "file": "lessons/g56-W-15.html", "st": "soon"}, {"id": "초5~6-쓰기-16", "g": "초5~6", "a": "쓰기", "lv": 4, "n": 16, "t": "형식에 맞게 여러 글을 써요", "goal": "일상과 학교생활에서 필요한 여러 유형의 글을 쓸 수 있어요.", "std": "일상과 학교생활에서 필요한 여러 유형의 글을 쓸 수 있다.", "codes": "W-4-4-1, W-4-4-2, W-4-4-3", "theme": "학교 행사", "acts": ["낱말·표현 익히기: 받는 사람, 첫인사, 본문, 끝인사, 쓴 사람, 보고서", "마음을 전하는 글을 형식(받는 사람, 첫인사, 본문, 끝인사, 쓴 사람 등)에 맞추어 작성한다.", "공식적인 글쓰기(보고서, 행사 안내, 선거 연설문 등)를 형식과 격식(제목, 인사말, 본문 서술, 맺음말 등)에 맞추어 쓴다.", "확인(진단형) 온라인 공간(학교 홈페이지나 학급 밴드 등)에 올릴 게시글을 쓸 때, 매체의 특성(인터넷 예절, 사진 첨부…"], "file": "lessons/g56-W-16.html", "st": "soon"}];